window.VN_BUNDLE={"game.json":"{\n \"title\": \"雨宿りの貸本屋\",\n \"scenes\": [\n  \"scene01.md\",\n  \"scene02.md\",\n  \"scene03.md\",\n  \"scene04.md\",\n  \"scene05.md\",\n  \"scene06.md\",\n  \"scene07.md\",\n  \"scene08.md\",\n  \"scene09.md\",\n  \"scene10.md\"\n ],\n \"extra\": [\n  \"ending_a.md\",\n  \"ending_b.md\",\n  \"ending_c.md\"\n ],\n \"flags\": {\n  \"trust_shiori\": 0,\n  \"told_chikage\": 0,\n  \"found_stamp\": 0,\n  \"chose_shiori\": 0,\n  \"answer_later\": 0\n },\n \"flagLimits\": {\n  \"trust_shiori\": [\n   0,\n   3\n  ]\n },\n \"endings\": [\n  {\n   \"id\": \"A\",\n   \"label\": \"ending_A\",\n   \"when\": \"trust_shiori >= 3 && found_stamp && !told_chikage\"\n  },\n  {\n   \"id\": \"C\",\n   \"label\": \"ending_C\",\n   \"when\": \"trust_shiori < 2 && answer_later\"\n  },\n  {\n   \"id\": \"B\",\n   \"label\": \"ending_B\",\n   \"when\": \"trust_shiori >= 2\"\n  }\n ],\n \"defaultEnding\": \"ending_B\",\n \"names\": {\n  \"ja\": {\n   \"shiori\": \"栞\",\n   \"chikage\": \"千景\",\n   \"soichiro\": \"宗一郎\"\n  },\n  \"en\": {\n   \"shiori\": \"Shiori\",\n   \"chikage\": \"Chikage\",\n   \"soichiro\": \"Soichiro\"\n  },\n  \"zh\": {\n   \"shiori\": \"栞\",\n   \"chikage\": \"千景\",\n   \"soichiro\": \"宗一郎\"\n  }\n },\n \"colors\": {\n  \"shiori\": \"#2f5d50\",\n  \"chikage\": \"#b5774a\",\n  \"soichiro\": \"#6b6f78\",\n  \"minato\": \"#3d4f73\"\n },\n \"bgs\": {\n  \"street_rain\": {\n   \"label\": {\n    \"ja\": \"商店街（雨）\",\n    \"en\": \"Shopping arcade (rain)\",\n    \"zh\": \"商店街（雨）\"\n   },\n   \"colors\": [\n    \"#4a5866\",\n    \"#2c3540\"\n   ]\n  },\n  \"shop_rain\": {\n   \"label\": {\n    \"ja\": \"貸本屋 店内（夕・雨）\",\n    \"en\": \"Lending library (evening, rain)\",\n    \"zh\": \"租书屋 店内（傍晚・雨）\"\n   },\n   \"colors\": [\n    \"#6b5440\",\n    \"#3a2c22\"\n   ]\n  },\n  \"shop_night\": {\n   \"label\": {\n    \"ja\": \"貸本屋 店内（夜）\",\n    \"en\": \"Lending library (night)\",\n    \"zh\": \"租书屋 店内（夜）\"\n   },\n   \"colors\": [\n    \"#8a6232\",\n    \"#2a1d12\"\n   ]\n  },\n  \"library\": {\n   \"label\": {\n    \"ja\": \"高校の図書室\",\n    \"en\": \"School library\",\n    \"zh\": \"高中图书室\"\n   },\n   \"colors\": [\n    \"#9aa58a\",\n    \"#5e6b55\"\n   ]\n  },\n  \"shrine_steps\": {\n   \"label\": {\n    \"ja\": \"神社の石段（夜）\",\n    \"en\": \"Shrine steps (night)\",\n    \"zh\": \"神社石阶（夜）\"\n   },\n   \"colors\": [\n    \"#2e3350\",\n    \"#141726\"\n   ]\n  },\n  \"seawall_eve\": {\n   \"label\": {\n    \"ja\": \"防波堤（夕方）\",\n    \"en\": \"Seawall (evening)\",\n    \"zh\": \"防波堤（傍晚）\"\n   },\n   \"colors\": [\n    \"#d69a6a\",\n    \"#5a6f8f\"\n   ]\n  },\n  \"seawall_night\": {\n   \"label\": {\n    \"ja\": \"防波堤（夜）\",\n    \"en\": \"Seawall (night)\",\n    \"zh\": \"防波堤（夜）\"\n   },\n   \"colors\": [\n    \"#1f2d4a\",\n    \"#0a0f1c\"\n   ]\n  },\n  \"letter_cg\": {\n   \"label\": {\n    \"ja\": \"手紙（CG）\",\n    \"en\": \"Letter (CG)\",\n    \"zh\": \"信（CG）\"\n   },\n   \"colors\": [\n    \"#efe6d2\",\n    \"#d8cbb0\"\n   ]\n  },\n  \"black\": {\n   \"label\": {\n    \"ja\": \"\",\n    \"en\": \"\",\n    \"zh\": \"\"\n   },\n   \"colors\": [\n    \"#000\",\n    \"#000\"\n   ]\n  },\n  \"hospital_room\": {\n   \"label\": {\n    \"ja\": \"病室\",\n    \"en\": \"Hospital room\",\n    \"zh\": \"病房\"\n   },\n   \"colors\": [\n    \"#c9d3d6\",\n    \"#8e9a9e\"\n   ],\n   \"image\": \"img/hospital_room.jpg\"\n  }\n },\n \"languages\": {\n  \"ja\": \"日本語\",\n  \"en\": \"English\",\n  \"zh\": \"中文\"\n },\n \"fallbackLanguage\": \"ja\",\n \"_endings_note\": \"Checked top to bottom; first true 'when' wins, else defaultEnding. Scene 10 also has an explicit [if chose_shiori && trust_shiori < 2 -> ending_B].\",\n \"ui\": {\n  \"ja\": {\n   \"start\": \"はじめから\",\n   \"load\": \"つづきから\",\n   \"config\": \"設定\",\n   \"back\": \"戻る\",\n   \"save\": \"セーブ\",\n   \"loadT\": \"ロード\",\n   \"slot\": \"スロット\",\n   \"empty\": \"— 空き —\",\n   \"log\": \"バックログ\",\n   \"speed\": \"文字速度\",\n   \"autoWait\": \"オート待ち時間\",\n   \"skipAll\": \"未読もスキップ\",\n   \"lang\": \"言語\",\n   \"toTitle\": \"タイトルに戻りますか？\",\n   \"menu\": [\n    \"AUTO\",\n    \"SKIP\",\n    \"LOG\",\n    \"SAVE\",\n    \"LOAD\",\n    \"CONFIG\",\n    \"TITLE\"\n   ],\n   \"title\": \"雨宿りの貸本屋\"\n  },\n  \"en\": {\n   \"start\": \"New Game\",\n   \"load\": \"Continue\",\n   \"config\": \"Settings\",\n   \"back\": \"Back\",\n   \"save\": \"Save\",\n   \"loadT\": \"Load\",\n   \"slot\": \"Slot \",\n   \"empty\": \"— empty —\",\n   \"log\": \"Backlog\",\n   \"speed\": \"Text speed\",\n   \"autoWait\": \"Auto-advance delay\",\n   \"skipAll\": \"Skip unread text\",\n   \"lang\": \"Language\",\n   \"toTitle\": \"Return to the title screen?\",\n   \"menu\": [\n    \"AUTO\",\n    \"SKIP\",\n    \"LOG\",\n    \"SAVE\",\n    \"LOAD\",\n    \"CONFIG\",\n    \"TITLE\"\n   ],\n   \"title\": \"The Lending Library in the Rain\"\n  },\n  \"zh\": {\n   \"start\": \"开始游戏\",\n   \"load\": \"继续游戏\",\n   \"config\": \"设置\",\n   \"back\": \"返回\",\n   \"save\": \"存档\",\n   \"loadT\": \"读档\",\n   \"slot\": \"存档位\",\n   \"empty\": \"— 空 —\",\n   \"log\": \"历史记录\",\n   \"speed\": \"文字速度\",\n   \"autoWait\": \"自动播放等待\",\n   \"skipAll\": \"跳过未读文本\",\n   \"lang\": \"语言\",\n   \"toTitle\": \"返回标题画面吗？\",\n   \"menu\": [\n    \"自动\",\n    \"快进\",\n    \"记录\",\n    \"存档\",\n    \"读档\",\n    \"设置\",\n    \"标题\"\n   ],\n   \"title\": \"避雨的租书屋\"\n  }\n },\n \"nameAliases\": {\n  \"_note\": \"Localized speaker name (as written before ':') -> character id. Display uses the name as written; sprites/colors use the id. Source: loc/glossary.md\",\n  \"ja\": {\n   \"湊\": \"minato\",\n   \"篠宮 湊\": \"minato\",\n   \"栞\": \"shiori\",\n   \"久世 栞\": \"shiori\",\n   \"千景\": \"chikage\",\n   \"早瀬 千景\": \"chikage\",\n   \"宗一郎\": \"soichiro\",\n   \"久世 宗一郎\": \"soichiro\",\n   \"遥\": \"haruka\",\n   \"水瀬 遥\": \"haruka\",\n   \"魚屋のおかみさん\": \"fishmonger\"\n  },\n  \"en\": {\n   \"Minato\": \"minato\",\n   \"Minato Shinomiya\": \"minato\",\n   \"Shiori\": \"shiori\",\n   \"Shiori Kuze\": \"shiori\",\n   \"Chikage\": \"chikage\",\n   \"Chikage Hayase\": \"chikage\",\n   \"Soichiro\": \"soichiro\",\n   \"Soichiro Kuze\": \"soichiro\",\n   \"Haruka\": \"haruka\",\n   \"Haruka Minase\": \"haruka\",\n   \"Fishmonger's wife\": \"fishmonger\",\n   \"The fishmonger's wife\": \"fishmonger\"\n  },\n  \"zh\": {\n   \"湊\": \"minato\",\n   \"篠宫 湊\": \"minato\",\n   \"栞\": \"shiori\",\n   \"久世 栞\": \"shiori\",\n   \"千景\": \"chikage\",\n   \"早濑 千景\": \"chikage\",\n   \"宗一郎\": \"soichiro\",\n   \"久世 宗一郎\": \"soichiro\",\n   \"遥\": \"haruka\",\n   \"水濑 遥\": \"haruka\",\n   \"鱼店老板娘\": \"fishmonger\"\n  }\n },\n \"endingTitles\": {\n  \"_note\": \"Ending card text per language, keyed by ending id (from 'END X' in the [title] tag, else the resolved ending). Falls back to the tag text. Names from loc/glossary.md.\",\n  \"ja\": {\n   \"A\": \"END A「栞のしおり」\",\n   \"B\": \"END B「雨上がり」\",\n   \"C\": \"END C「となりの席」\"\n  },\n  \"en\": {\n   \"A\": \"END A: Shiori's Bookmark\",\n   \"B\": \"END B: After the Rain\",\n   \"C\": \"END C: The Seat Beside Me\"\n  },\n  \"zh\": {\n   \"A\": \"END A《栞的书签》\",\n   \"B\": \"END B《雨停之后》\",\n   \"C\": \"END C《身旁的座位》\"\n  }\n }\n}","scenes/ja/scene01.md":"# Scene 01 雨の貸本屋\n\n[bg street_rain]\n[bgm bgm_rain]\n[se rain_heavy]\n\n湊: （……天気予報、外れすぎだろ）\n\n湊: （鞄を頭にのせて走る。商店街のアーケードは途中で切れている）\n\n湊: （シャッターばかりの通りで、一軒だけ灯りがついていた）\n\n[se door_slide]\n[se door_bell]\n[bg shop_rain]\n[se rain_loop]\n\n湊: すみません、ちょっとだけ――\n\n[show shiori cold]\n\n栞: 閉店は七時です。\n\n湊: あ、雨宿りで。すぐ出ます。\n\n栞: ……傘立て、そこです。濡れたまま棚に触らないでください。\n\n湊: （傘はない。言わないでおいた）\n\n湊: （古い紙の匂いがする。天井まで本が詰まっていて、背表紙はどれも日に焼けている）\n\n湊: ここ、本屋？\n\n[show shiori normal]\n\n栞: 貸本屋です。\n\n湊: かしほんや。\n\n栞: 借りて、読んで、返す店です。\n\n湊: ……ああ。\n\n湊: （そういえば、と鞄を探る。今朝、姉に押しつけられた一冊）\n\n湊: これ、たぶんここのです。姉が昔借りたまま、忘れてたって。\n\n[show shiori surprised]\n\n栞: ……「久世貸本店」。うちのですね。\n\n栞: 貸出日、十年前ですけど。\n\n湊: すみません。延滞料とか……\n\n栞: うちはそういうの、取ってないので。\n\n[se book_drop]\n\n湊: あ。\n\n湊: （受け取ろうとした栞の手から、本が落ちた）\n\n[se paper]\n\n湊: （ページのあいだから、白い封筒が滑り出る）\n\n湊: 何か挟まってた。\n\n[show shiori normal]\n\n栞: 「久世さま」……\n\n湊: 消印、これも十年前だ。\n\n栞: 封、開いてない。\n\n湊: （宛名の字は丸くて、少し右に傾いていた）\n\n湊: 久世さまって、店の人？\n\n栞: 祖父です。\n\n湊: じゃあ、おじいさん宛ての――\n\n[show shiori cold]\n\n栞: 祖父は今、ここにいません。\n\n湊: （それ以上は聞くな、という言い方だった）\n\n湊: （雨の音だけが続く）\n\n[choice]\n- 「開けてみない？」 -> choice01_a\n- 「おじいさんに渡したほうがいいよ」 -> choice01_b\n[/choice]\n\n[label choice01_a]\n\n湊: 開けてみない？\n\n[show shiori cold]\n\n栞: 人の手紙ですよ。\n\n湊: ……だよな。ごめん。\n\n栞: でも。\n\n湊: ん？\n\n[show shiori normal]\n\n栞: ……いえ。なんでもないです。\n\n[jump scene01_end]\n\n[label choice01_b]\n[flag trust_shiori +1]\n\n湊: おじいさんに渡したほうがいいよ。十年待ってたんだし。\n\n[show shiori surprised]\n\n栞: 待ってたのは、手紙のほうですか。\n\n湊: どっちもじゃない？\n\n[show shiori normal]\n\n栞: ……変な人ですね。\n\n湊: よく言われる。\n\n[jump scene01_end]\n\n[label scene01_end]\n\n[se rain_loop]\n\n湊: （小降りになってきた）\n\n湊: じゃあ、俺はこれで。本、返せてよかった。\n\n栞: あの。\n\n[show shiori sad]\n\n栞: この店、今月で閉めるんです。\n\n湊: え。\n\n栞: まだ誰にも言ってないので。……言わないでください。\n\n湊: なんで俺に言ったの。\n\n栞: なんででしょうね。\n\n[show shiori normal]\n\n栞: 十年ぶりに本を返しに来た人だから、かもしれません。\n\n[se door_bell]\n\n湊: （外に出ると、雨はまだ細く降っていた）\n\n湊: （振り返ると、ガラス戸の向こうで、彼女が封筒を灯りにかざしていた）\n\n[bgm stop]\n[bg black]\n","scenes/ja/scene02.md":"# Scene 02 翌朝の教室〜図書室\n\n[bg library]\n[bgm bgm_daily]\n[se school_chime]\n\n湊: （翌朝。雨は夜のうちに上がっていた）\n\n湊: （一限から四限まで、黒板の字がほとんど頭に入らなかった）\n\n湊: （丸い字。右に傾いた宛名。十年前の消印）\n\n湊: （昼休み、気づいたら図書室にいた。ここなら誰にも話しかけられない）\n\n[show chikage normal]\n\n千景: いた。\n\n湊: ……なんでわかった。\n\n千景: 湊が昼休みに消えるときは、だいたいここか屋上。屋上は今日びしょびしょだし。\n\n湊: 探偵かよ。\n\n千景: 図書委員だよ。今日カウンター当番なの。\n\n湊: （千景はカウンターに肘をついて、返却された本の山を崩しはじめた）\n\n[show chikage smile]\n\n千景: で？\n\n湊: で、って。\n\n千景: 顔に書いてあるよ。朝からずっと、なんか考えてる顔。\n\n湊: 別に。数学の小テストのこと考えてた。\n\n千景: 湊が小テストの心配したことなんて、小学校から一回もないじゃん。\n\n湊: ……。\n\n千景: ほら。\n\n湊: （言い返せない。千景とは幼稚園からの付き合いで、こういうときに嘘が通ったためしがない）\n\n[show chikage normal]\n\n千景: あ、そうだ。湊、商店街のほう住んでたよね。\n\n湊: 住んでるのはその裏。\n\n千景: 「久世貸本店」って知ってる？ 魚屋さんの並びの、古い店。\n\n湊: （手が止まった）\n\n湊: ……知ってる、けど。\n\n千景: 書庫の整理してたら、古い台帳が出てきてさ。昔、この図書室とあの店、提携してたんだって。\n\n湊: 提携？\n\n千景: 図書室にない本を、あの店から借りて生徒に回してたみたい。けっこう前の話だけどね。先生も「ああ、あったねえ」くらいしか覚えてなかった。\n\n湊: へえ。\n\n[show chikage surprised]\n\n千景: ……今、「へえ」の言い方おかしかった。\n\n湊: おかしくない。\n\n千景: おかしい。湊が本当に興味ないときは「ふーん」だもん。\n\n湊: （そこまで把握されてるのか）\n\n[show chikage normal]\n\n千景: なに。あの店となんかあったの？\n\n湊: （昨日の封筒のことを思い出す。それから、閉店のこと）\n\n湊: （閉店のほうは、言わないでくれと言われた。手紙のほうは――言われてない）\n\n[choice]\n- 手紙のことを千景に話す -> choice02_a\n- 曖昧にごまかす -> choice02_b\n[/choice]\n\n[label choice02_a]\n[flag told_chikage = 1]\n\n湊: ……昨日、雨宿りであの店に入ったんだよ。\n\n湊: 姉ちゃんが十年前に借りっぱなしだった本、返しに。そしたら中から手紙が出てきた。\n\n[show chikage surprised]\n\n千景: 手紙？\n\n湊: 封も開いてないやつ。宛名は店のおじいさんで、消印が十年前。\n\n千景: え、なにそれ。普通に事件じゃん。\n\n湊: 事件ではないだろ。\n\n千景: 十年届かなかった手紙だよ？ 十分事件だって。\n\n[show chikage smile]\n\n千景: で、差出人は？\n\n湊: 書いてなかった。字が丸かったくらい。\n\n千景: 丸い字。女子っぽいってこと？\n\n湊: たぶん。\n\n千景: ふーん。\n\n湊: ……なんだよ。\n\n千景: べつに？ 店番の子もいた？\n\n湊: いた。孫だって。\n\n千景: その子かわいいの？\n\n湊: 関係ないだろ。\n\n千景: 否定はしないんだ。\n\n湊: （昼休みの残り十分、千景は台帳をめくりながらずっとにやにやしていた）\n\n[show chikage normal]\n\n千景: 提携の記録、もうちょっと調べといてあげる。何か出てきたら教えるね。\n\n湊: ……助かる。\n\n[jump scene02_end]\n\n[label choice02_b]\n\n湊: 昔、姉ちゃんがあそこで本借りてたらしい。それだけ。\n\n[show chikage pout]\n\n千景: それだけ？\n\n湊: それだけ。\n\n千景: ……あっそ。\n\n湊: （千景は返却本のバーコードを、いつもより強めに読み取りはじめた）\n\n[show chikage normal]\n\n千景: 言いたくないなら別にいいけど。湊、隠しごと下手だからね。\n\n湊: 知ってる。\n\n千景: 知ってるならやめなよ。\n\n湊: （それには答えなかった）\n\n[label scene02_end]\n\n[se school_chime]\n\n湊: （予鈴が鳴る。千景が本の山を抱えて書庫に消えていく）\n\n湊: （窓の外は、また曇りはじめていた）\n\n湊: （放課後、もう一度あの店に行こう。理由は――あとで考えればいい）\n\n[bg black]\n[se door_slide]\n\n湊: （帰り道、姉にメッセージを送った。「十年前の本、なんで返さなかったの」）\n\n湊: （返事は三分後に来た。「返したつもりだった」「なんかあった？」）\n\n湊: （「封筒挟まってた」と打って、消した。「別に」と送った）\n\n湊: （「あそこのおじいさん元気？ 怖いけど優しい人だったよ」）\n\n湊: （既読をつけたまま、しばらく画面を見ていた）\n\n[bgm stop]\n[bg black]\n","scenes/ja/scene03.md":"# Scene 03 貸本屋、二度目\n\n[bg street_rain]\n[bgm bgm_rain]\n[se rain_loop]\n\n湊: （放課後。予報どおり、また降り出した）\n\n湊: （今日はコンビニで傘を買った。透明のやつ）\n\n[se door_slide]\n[se door_bell]\n[bg shop_rain]\n\n[show shiori surprised]\n\n栞: ……。\n\n湊: どうも。\n\n[show shiori cold]\n\n栞: 本、ほかにも借りっぱなしでしたか。\n\n湊: いや。\n\n栞: じゃあ、雨宿りですか。傘、持ってますよね。\n\n湊: 持ってる。\n\n栞: ……。\n\n湊: 手伝おうかと思って。閉めるなら、片付けとかあるだろ。\n\n[show shiori normal]\n\n栞: 頼んでません。\n\n湊: 知ってる。\n\n湊: （栞は少し黙って、それから店の奥を指さした）\n\n栞: 奥の三段目から下。全部、箱に詰めます。背表紙を上にして、番号順に。\n\n湊: 了解。\n\n栞: 濡れた手で触らないでください。\n\n湊: 拭いた。\n\n栞: 傘も外に。\n\n湊: ……はい。\n\n[se footsteps_wet]\n\n湊: （作業は思ったより地味だった。本を抜いて、番号を確かめて、箱に入れる。その繰り返し）\n\n湊: （栞はレジの横で、黙って帳簿をつけている。ペンの音と、雨の音だけ）\n\n湊: この番号、何？\n\n栞: 仕入れた順です。祖父が全部手で書きました。\n\n湊: 全部？\n\n栞: 全部。四千二百十一冊。\n\n湊: すごいな。\n\n栞: 字が汚いので、半分くらい読めませんけど。\n\n湊: （冗談なのかどうか、判断がつかなかった）\n\n湊: おじいさん、今日はいないの。\n\n[show shiori sad]\n\n栞: 入院してます。春から。\n\n湊: ……そっか。\n\n栞: 心臓です。手術は終わってて、命がどうこうって話じゃないです。ただ、もう店には立てないって。\n\n湊: それで閉めるのか。\n\n栞: 私ひとりでは回せないので。\n\n湊: （ペンの音が止まっていた）\n\n栞: 手紙、昨日、病院に持っていきました。\n\n湊: 渡した？\n\n栞: 見せました。宛名だけ。\n\n湊: なんて？\n\n栞: 「知らない字だ」って。\n\n湊: ……。\n\n栞: それだけ言って、窓のほう向いちゃいました。\n\n[show shiori normal]\n\n栞: だから、まだ私が持ってます。\n\n湊: （栞はエプロンのポケットから、封筒の角を少しだけ出してみせた）\n\n湊: じゃあ、誰が書いたか調べればいいんじゃないか。\n\n栞: 調べてどうするんですか。\n\n湊: 知らない字じゃなかったら、受け取るかもしれないだろ。\n\n[show shiori surprised]\n\n栞: ……。\n\n湊: 十年前の消印なら、十年前に店に来てた誰かかもしれない。記録とか残ってないの。\n\n栞: 貸出カードなら。返ってきた本のカードは、全部取ってあります。\n\n湊: 全部？\n\n栞: 祖父、そういうの捨てない人なので。\n\n[se paper]\n\n湊: （栞が奥から靴箱を三つ持ってきた。中には、黄ばんだ厚紙のカードがぎっしり詰まっている）\n\n湊: （日付と、名前と、返却印。十年前の束だけでも百枚以上ある）\n\n栞: 十年前の、梅雨の時期だけに絞ります。消印、六月なので。\n\n湊: 姉ちゃんの名前もあるかな。\n\n栞: 篠宮さん。……ありました。同じ週です。\n\n湊: （姉の字は、今と変わらずひどかった）\n\n湊: （残りのカードを二人で手分けしてめくっていく）\n\n[choice]\n- 貸出カードの裏を一枚ずつ確かめる -> choice03_a\n- 封筒の字をもう一度よく見る -> choice03_b\n[/choice]\n\n[label choice03_a]\n[flag found_stamp = 1]\n\n湊: （表の名前だけ見ていても、決め手がない。裏返してみる）\n\n湊: （ほとんどは白紙だった。でも、何枚かに、薄い朱色の丸い印が押してある）\n\n湊: これ、何の印？\n\n[show shiori surprised]\n\n栞: ……「潮見高校図書室」。\n\n湊: うちの学校だ。\n\n栞: 提携してたんです。昔、学校の図書室に本を貸し出してて。\n\n湊: 今日、それ聞いた。\n\n栞: 誰に。\n\n湊: 図書委員の知り合い。\n\n湊: （印のある束を並べる。その中の古い一枚、もっと昔の日付のカードに、見覚えのある字があった）\n\n湊: これ。\n\n栞: 「図書室扱い　担当」……名前のところ、かすれてますね。\n\n湊: でも、この字。\n\n[show shiori normal]\n\n栞: ……丸い。右に傾いてる。\n\n湊: 封筒と同じだ。\n\n栞: 二十年以上前のカードですよ、これ。\n\n湊: うん。\n\n栞: 十年前の手紙の人が、もっと前にもうちに来てた……？\n\n湊: しかも、学校の図書室の担当として。\n\n湊: （栞はそのカードを、封筒と並べて、しばらく見ていた）\n\n[jump scene03_end]\n\n[label choice03_b]\n\n湊: ちょっと、封筒見せて。\n\n栞: 開けないでくださいよ。\n\n湊: 開けない。\n\n湊: （宛名の「久世さま」。ハネが短くて、丸い。最後の点がやけに大きい）\n\n湊: 女の人の字、だと思う。若い感じ。\n\n[show shiori normal]\n\n栞: そうですか？\n\n湊: 姉ちゃんの友達が、こういう字書いてた。ノートの端にハート描くタイプ。\n\n栞: 偏見です。\n\n湊: たぶんな。\n\n湊: （結局、カードの束からは、それ以上の手がかりは出てこなかった）\n\n[label scene03_end]\n\n[se rain_loop]\n\n湊: （気づくと、窓の外が暗くなっていた）\n\n[show shiori normal]\n\n栞: 七時です。\n\n湊: 閉店？\n\n栞: 閉店です。\n\n湊: 明日も来ていい？\n\n栞: ……箱、まだ残ってるので。\n\n湊: それ、いいってこと？\n\n[show shiori cold]\n\n栞: 濡れた手で触らないなら。\n\n[bgm stop]\n[bg black]\n","scenes/ja/scene04.md":"# Scene 04 商店街の雨\n\n[bg street_rain]\n[bgm bgm_mystery]\n[se rain_loop]\n\n湊: （三日目。箱詰めは半分まで進んだ）\n\n湊: （その日、栞は店の札を「準備中」にして、エプロンを外した）\n\n[show shiori normal]\n\n栞: 聞き込みに行きます。\n\n湊: 聞き込み。\n\n栞: 十年前からこの商店街にいる人なら、うちの常連を覚えてるかもしれないので。\n\n湊: 刑事ドラマみたいだな。\n\n栞: 刑事ドラマなら、もっと人がいます。\n\n湊: （確かに、シャッターの数のほうが多い）\n\n湊: （栞は古い藍色の傘を広げた。大きくて、骨が一本だけ曲がっている）\n\n[se umbrella_open]\n\n栞: 祖父のです。\n\n湊: でかいな。\n\n栞: 二人入れるように、って買ったらしいです。誰と入るつもりだったのかは知りません。\n\n湊: （俺はコンビニの透明な傘を差して、その隣を歩いた）\n\n[se footsteps_wet]\n\n湊: （布団屋のおじいさんは、店のことは覚えていたが、客のことは覚えていなかった）\n\n湊: （たばこ屋は、もう五年前に代替わりしていた）\n\n湊: （花屋のお姉さんは、栞を見て「大きくなったねえ」と三回言った）\n\n[show shiori sad]\n\n栞: ……収穫、なしですね。\n\n湊: 栞、ここで育ったの。\n\n栞: 六歳から。\n\n湊: その前は？\n\n栞: 東京です。あんまり覚えてないです。\n\n湊: （それ以上は聞かなかった）\n\n[show shiori normal]\n\n栞: あと一軒。\n\n湊: どこ？\n\n栞: 魚屋さん。あそこのおかみさん、この商店街のこと全部知ってるので。\n\n[se footsteps_wet]\n\n魚屋のおかみさん: あらあ、栞ちゃん！ 久しぶりじゃない、おじいちゃんどう？\n\n栞: 元気です。退屈してます。\n\n魚屋のおかみさん: そりゃよかった。そっちの子は？ 彼氏？\n\n[show shiori cold]\n\n栞: 違います。\n\n湊: 違います。\n\n魚屋のおかみさん: 揃ってるわねえ。\n\n湊: （栞が、少しだけ俺から離れた）\n\n栞: 十年くらい前、うちの店によく来てたお客さん、覚えてませんか。女の人で。\n\n魚屋のおかみさん: 十年前ねえ……あの頃はまだ、お客さんけっこういたからねえ。\n\n魚屋のおかみさん: あ、でも。\n\n栞: でも？\n\n魚屋のおかみさん: 十年前じゃなくて、もっと前よ。ずうっと前。あそこでいっつも何か書いてた女の子がいたわ。高校生の。\n\n湊: 書いてた？\n\n魚屋のおかみさん: 窓際の、小さい机あるでしょ。あそこに座って、本読むんじゃなくて、ノートに何か書いてるの。宗一郎さん、怖い顔して黙って見てたけど、追い出しはしなかったわねえ。\n\n栞: ……その人、名前は。\n\n魚屋のおかみさん: さあ、名前までは。よく笑う子だったわよ。宗一郎さんがあんなに喋ってるの、あの頃しか見たことないもの。\n\n[show shiori surprised]\n\n栞: 祖父が、喋ってた……？\n\n魚屋のおかみさん: そうよお。今じゃ考えられないでしょ。\n\n魚屋のおかみさん: そのうち来なくなっちゃって。卒業したのかしらね。宗一郎さん、しばらく元気なかったわ。\n\n魚屋のおかみさん: ……あら、ごめんね、古い話ばっかり。はい、これ持ってって。おじいちゃんに。\n\n湊: （栞の腕に、ビニール袋に入ったアジの干物が押しつけられた）\n\n[bgm bgm_rain]\n\n湊: （帰り道、雨が強くなった）\n\n[se rain_heavy]\n\n湊: （透明な傘が、ばたばたと風にあおられる）\n\n[se thunder_far]\n\n湊: あ。\n\n湊: （骨が二本、まとめて裏返った）\n\n[show shiori normal]\n\n栞: ……三百円ですもんね。\n\n湊: 五百円だよ。\n\n栞: 同じです。\n\n湊: （栞は黙って、藍色の傘を少しこちらに傾けた）\n\n湊: （二人入れるように買った傘だ。実際、二人入れた。ぎりぎりで）\n\n湊: （肩が触れない距離を保つのが、思ったより難しい）\n\n[choice]\n- 「傘、俺が持つよ」 -> choice04_a\n- 何も言わずに歩く -> choice04_b\n[/choice]\n\n[label choice04_a]\n[flag trust_shiori +1]\n\n湊: 傘、俺が持つよ。\n\n[show shiori surprised]\n\n栞: え。\n\n湊: 栞、手首曲がってる。ずっとそれだと疲れるだろ。\n\n栞: ……背、高いからって。\n\n湊: 低いほうが持つと、高いほうの頭に骨が刺さる。\n\n[show shiori smile]\n\n栞: ふふ。\n\n湊: （初めて、ちゃんと笑ったのを見た気がした）\n\n栞: じゃあ、お願いします。\n\n湊: （受け取った柄は、思っていたより冷たかった）\n\n湊: （栞は干物の袋を胸に抱えて、半歩だけ内側に寄った）\n\n栞: 篠宮くんの肩、濡れてますよ。\n\n湊: 傘持ちの宿命。\n\n栞: そういうの、どこで覚えるんですか。\n\n湊: 姉ちゃん。\n\n栞: お姉さん、いろいろ教えてくれるんですね。本は返さないのに。\n\n[jump scene04_end]\n\n[label choice04_b]\n\n湊: （何か言おうとして、やめた）\n\n湊: （栞は前を見たまま、傘の柄を両手で握っている）\n\n湊: （干物の袋が、ときどき俺の腕に当たった）\n\n[show shiori normal]\n\n栞: ……。\n\n湊: ……。\n\n湊: （気まずい、とは少し違う沈黙だった）\n\n[label scene04_end]\n\n[bg shop_rain]\n[se door_bell]\n\n湊: （店に着くと、栞は傘を閉じて、曲がった骨を指で直そうとした。直らなかった）\n\n[show shiori normal]\n\n栞: よく笑う子、って。\n\n湊: うん。\n\n栞: 祖父の口から、そういう言葉が出るとこ、想像できないです。\n\n湊: でも、おかみさんは見たって。\n\n栞: ……私、祖父のこと、何も知らないのかもしれません。\n\n[bgm stop]\n[bg black]\n","scenes/ja/scene05.md":"# Scene 05 図書室の古い記録\n\n[bg library]\n[bgm bgm_mystery]\n[se school_chime]\n\n湊: （翌日の放課後。図書室の奥、普段は鍵がかかっている書庫の前）\n\n[show chikage normal]\n\n千景: はい、これ。古い図書委員の名簿。二十年分くらいあるよ。\n\n湊: ……なんで俺が来るってわかった。\n\n[if told_chikage -> s05_told]\n\n千景: わかるよ。昨日、商店街で傘差して歩いてたでしょ。貸本屋の子と。\n\n湊: 見てたのかよ。\n\n[show chikage pout]\n\n千景: 見えたの。魚屋さんの前で。……で、あの店の何を調べてるの？ 提携のこと聞いたときから、変だったもん。\n\n湊: （ここまで来たら、ごまかしようがない）\n\n湊: ……昔、あの店に来てた人を探してる。図書室の担当だったかもしれない人。\n\n千景: ふーん。それ、あたしにも言えないこと？\n\n湊: 今は。\n\n[show chikage normal]\n\n千景: ……ま、いいや。名簿見るなら書庫の鍵いるでしょ。開けたげる。\n\n[jump s05_search]\n\n[label s05_told]\n\n千景: 言ったじゃん、調べといてあげるって。\n\n[show chikage smile]\n\n千景: それと、今日はもうひとり呼んであるの。\n\n湊: は？\n\n[se door_slide]\n\n[show shiori normal]\n\n栞: ……失礼します。\n\n湊: 栞？\n\n栞: 早瀬さんから、店に電話があって。「名簿出すから来て」って。\n\n千景: 店の電話番号、台帳に載ってたんだよね。\n\n湊: 勝手に……。\n\n千景: 湊が言ったんでしょ、手紙の人探してるって。本人がいたほうが早いじゃん。\n\n[show shiori cold]\n\n栞: 本人じゃないです。私は店番なので。\n\n千景: はいはい。久世さん、よろしくね。早瀬千景です。湊とは幼稚園から一緒。\n\n栞: ……久世です。\n\n湊: （千景がにこにこしている。栞は他校の制服で、少し居心地が悪そうだった）\n\n[label s05_search]\n\n[se paper]\n\n湊: （名簿は、年度ごとに綴じられた薄いファイルだった。手書きの名前、クラス、担当曜日）\n\n湊: （ひとつの年度に、十人から十五人。二十年分なら、二百人以上になる）\n\n[if found_stamp -> s05_found]\n\n湊: 担当が丸い字の女子、ってだけじゃな……。\n\n[show chikage normal]\n\n千景: 女子だけで百人いるよ。\n\n湊: だよな。\n\n千景: 提携の担当がいたなら、そっちの記録はないの？\n\n湊: 店のほうには何も残ってなかった。\n\n千景: うーん……。\n\n湊: （ファイルを片っ端からめくる。字の丸い名前はいくつもある。けど、どれも決め手にならない）\n\n湊: （ひとつだけ、引っかかるページがあった。二十数年前の年度。担当欄の「貸本屋（久世）」の横に、名前がひとつだけ書いてある）\n\n湊: （その名前の上に、インクがこぼれた染みがあった。読めるのは、最後の一文字だけ）\n\n湊: 「遥」……か。\n\n千景: ハルカ？\n\n湊: 名字は読めない。\n\n千景: 遥って名前、けっこういるよ。\n\n湊: うん。\n\n湊: （それでも、メモに書き写しておいた。遥。貸本屋の担当。二十数年前）\n\n[jump s05_end]\n\n[label s05_found]\n\n湊: 印の押してあったカード、日付が二十二年前の秋だった。\n\n湊: （その年度のファイルを抜き出す）\n\n[show chikage surprised]\n\n千景: あ、これ。担当欄に「貸本屋（久世）」って書いてある。\n\n湊: 曜日担当じゃなくて、店との連絡係がいたのか。\n\n千景: しかも、ひとりだけ。\n\n湊: （名前を読む。丸い字で、右に少し傾いた、本人の筆跡で）\n\n湊: 「水瀬　遥」。\n\n[if told_chikage -> s05_shiori_hears]\n\n千景: みなせ、はるか。……知ってる人？\n\n湊: いや。\n\n湊: （でも、この字を知っている。封筒と同じ字だ）\n\n湊: （この名前を、栞に伝えなきゃいけない）\n\n[jump s05_end]\n\n[label s05_shiori_hears]\n\n[show shiori surprised]\n\n栞: ……。\n\n湊: 栞？\n\n栞: 水瀬は、母が結婚する前の名字です。\n\n[show chikage surprised]\n\n千景: え。\n\n栞: 遥は、母の名前です。\n\n湊: （書庫の空気が、急に冷えた気がした）\n\n[show shiori sad]\n\n栞: でも、母は東京の人のはずで。この町にいたなんて、聞いたことないです。\n\n千景: ……ごめん。あたし、軽い気持ちで呼んじゃった。\n\n栞: いえ。\n\n栞: 呼んでもらってなかったら、知らないままでした。\n\n[label s05_end]\n\n[se school_chime]\n\n[show chikage normal]\n\n千景: 下校のチャイム。書庫、閉めるよ。\n\n湊: ああ。\n\n千景: ねえ、湊。\n\n湊: ん。\n\n[show chikage sad]\n\n千景: 何でもない。……明日、話あるから、ちょっと時間ちょうだい。\n\n湊: （千景はそう言って、鍵をくるくる回しながら先に出ていった）\n\n[bgm stop]\n[bg black]\n","scenes/ja/scene06.md":"# Scene 06 神社の石段\n\n[bg shrine_steps]\n[bgm bgm_memory]\n[se rain_loop]\n\n湊: （その夜。店の前を通ったら、灯りが消えていた）\n\n湊: （なんとなく、坂の上の神社まで歩いた。石段の途中に、藍色の傘が開いたまま置いてあった）\n\n[show shiori normal]\n\n栞: ……なんでいるんですか。\n\n湊: そっちこそ。\n\n栞: 店にいると、箱ばっかり目に入るので。\n\n湊: （傘の下に、栞が膝を抱えて座っていた。雨はもうほとんど霧みたいになっている）\n\n湊: 座っていい？\n\n栞: 濡れてますよ、そこ。\n\n湊: もう濡れてる。\n\n[se rain_loop]\n\n湊: （しばらく、どちらも喋らなかった。下の方で、商店街の街灯がひとつずつ滲んでいる）\n\n[show shiori sad]\n\n栞: 母は、私が六歳のときに死にました。\n\n湊: ……。\n\n栞: 病気で。東京の病院で。そのあと、祖父に引き取られて、ここに来ました。\n\n栞: 父のことは、聞かないでください。私もよく知らないので。\n\n湊: 聞かない。\n\n栞: 祖父は、母の話を一度もしたことがないです。写真もない。仏壇に位牌があるだけ。\n\n栞: 小さい頃、一回だけ聞いたんです。「お母さんってどんな人だった」って。\n\n湊: なんて言われた。\n\n栞: 「本を大事にしない子だった」。\n\n湊: （思わず、変な声が出そうになった）\n\n[show shiori normal]\n\n栞: ……笑うところですよ、ここ。\n\n湊: 笑えないだろ。\n\n栞: 私は笑いました。ほかに何も言わないから。それしか、母のことを知らないから。\n\n[if found_stamp -> s06_know]\n\n湊: 栞のお母さんの名前、聞いていい？\n\n栞: 遥です。\n\n湊: （図書室の名簿。インクの染みの横に残っていた、一文字）\n\n湊: ……今日、学校の名簿で見た。二十何年前に、店との連絡係をやってた図書委員。名字は読めなかったけど、名前が「遥」だった。\n\n[show shiori surprised]\n\n栞: ……。\n\n湊: 魚屋のおかみさんが言ってた、窓際で書きものしてた女の子。封筒の丸い字。全部、同じ人なんじゃないかと思う。\n\n湊: 確かめたわけじゃない。俺の勘。\n\n栞: 母は、東京の人です。\n\n湊: 高校のときだけ、こっちにいたとか。\n\n栞: ……そんな話、聞いたことない。\n\n[jump s06_choice]\n\n[label s06_know]\n\n[if told_chikage -> s06_know_told]\n\n湊: 今日、学校の名簿で見つけた。二十二年前、あの店と図書室の連絡係をやってた図書委員。\n\n湊: 「水瀬遥」って人。封筒と、同じ字だった。\n\n[show shiori surprised]\n\n栞: ……水瀬。\n\n湊: 知ってる？\n\n栞: 母が結婚する前の名字です。名前も、遥。\n\n湊: （やっぱり、と思った。思っただけで、言わなかった）\n\n[jump s06_after_know]\n\n[label s06_know_told]\n\n栞: 昼間の名簿。……あれから、ずっと考えてました。\n\n湊: うん。\n\n[label s06_after_know]\n\n[show shiori sad]\n\n栞: 母は、東京の人だと思ってました。\n\n栞: 高校のとき、この町にいて。うちの店に通って。祖父と、喋ってて。\n\n栞: 祖父、「知らない字だ」って言ったんです。\n\n湊: ……知らないわけ、ないよな。\n\n栞: 知らないわけないです。\n\n[label s06_choice]\n\n湊: （栞がポケットから封筒を出した。角が少し柔らかくなっている。この数日、何度も触ったんだろう）\n\n[choice]\n- 「一緒に読もう」 -> choice06_a\n- 「栞が決めていい」 -> choice06_b\n[/choice]\n\n[label choice06_a]\n\n湊: 一緒に読もう。ひとりで開けるのがきついなら。\n\n[if trust_shiori < 1 -> s06_refuse]\n[flag trust_shiori +1]\n\n[show shiori surprised]\n\n栞: ……一緒に。\n\n湊: 俺が持ってきた本から出てきたんだし。半分くらいは俺の責任だろ。\n\n栞: どういう理屈ですか、それ。\n\n湊: 延滞料の代わり。\n\n[show shiori smile]\n\n栞: ……うち、延滞料取ってないって言ったよね。\n\n湊: （敬語が、少し崩れていた）\n\n栞: じゃあ、取る。開けるとき、隣にいて。\n\n湊: わかった。\n\n栞: 今じゃなくて。店で。ちゃんと明るいところで読みたい。\n\n[jump scene06_end]\n\n[label choice06_b]\n\n湊: 栞が決めていい。開けても、開けなくても。\n\n[if trust_shiori < 1 -> s06_refuse]\n[flag trust_shiori +1]\n\n[show shiori surprised]\n\n栞: ……私が？\n\n湊: 宛名はおじいさんだけど、書いたのは栞のお母さんだろ。俺が決めることじゃない。\n\n栞: 祖父の手紙を、私が開けていいと思いますか。\n\n湊: 思うかどうかは、俺じゃなくて栞が決めることだと思う。\n\n[show shiori blush]\n\n栞: 湊くんって、ずるいね。\n\n湊: （初めて名前で呼ばれた。指摘したら二度と呼ばれない気がしたので、黙っていた）\n\n栞: ……開ける。店で。祖父に読んで聞かせる前に、私が先に読む。\n\n栞: それくらいの権利、あると思うから。\n\n[jump scene06_end]\n\n[label s06_refuse]\n\n[show shiori cold]\n\n栞: ……まだ、開けられません。\n\n湊: そっか。\n\n栞: 篠宮くんに言われたからって、開けるものじゃないので。\n\n湊: （封筒が、またポケットに戻っていく）\n\n湊: （最初の日、開けてみないかと言ったのは俺だった。たぶん、栞はそれを覚えている）\n\n[show shiori normal]\n\n栞: でも、誰の手紙かは、わかりました。\n\n栞: ……それは、ありがとうございます。\n\n[label scene06_end]\n\n[se rain_loop]\n\n湊: （霧雨がやんだ。栞は傘を閉じて、石段を一段ずつ下りていった）\n\n湊: （途中で一度だけ振り返って、何か言いかけて、やめた）\n\n[bgm stop]\n[bg black]\n","scenes/ja/scene07.md":"# Scene 07 千景の忠告\n\n[bg street_rain]\n[bgm bgm_daily]\n[se rain_loop]\n\n湊: （翌日の放課後。校門のところで、千景が待っていた）\n\n[show chikage normal]\n\n千景: 時間ちょうだいって言ったでしょ。\n\n湊: 言われた。\n\n千景: 歩きながらでいいよ。どうせ商店街のほう行くんでしょ。\n\n湊: （図星だったので、何も言わずに並んだ）\n\n[se footsteps_wet]\n\n千景: 小学校のときさ、湊、川で亀拾ってきたの覚えてる？\n\n湊: ……覚えてない。\n\n千景: 拾ってきたの。で、名前つけて、毎日えさあげて、甲羅の模様スケッチして。\n\n千景: で、一ヶ月で飽きて、あたしが川に返しに行った。\n\n湊: それは覚えてる。千景が泣きながら怒ってた。\n\n[show chikage pout]\n\n千景: 泣いてない。\n\n湊: 泣いてた。\n\n千景: 怒ってはいた。\n\n[bg seawall_eve]\n[bgm bgm_heart]\n[se waves]\n\n湊: （商店街を抜けて、防波堤に出た。雨はやんでいて、雲の切れ目から西日が差している）\n\n[show chikage normal]\n\n千景: 湊はさ、気になったものに全部持ってかれるじゃん。で、わかっちゃったら、次に行く。\n\n湊: ……。\n\n千景: 責めてるんじゃないよ。そういうとこ、昔から見てたから。\n\n[if told_chikage -> s07_leak]\n[jump s07_confess]\n\n[label s07_leak]\n\n[show chikage sad]\n\n千景: あと、先に謝らせて。\n\n湊: 何を。\n\n千景: 昨日の夜、お母さんに貸本屋の話したの。手紙のこととか、あの子のお母さんのこととか。おもしろい話だと思って。\n\n千景: そしたらお母さん、「あそこ、もう閉めるらしいわね」って。\n\n湊: ……誰から。\n\n千景: わかんない。病院で誰かが聞いたのかも。でも、あたしが話題にしたから、お母さん、今朝パート先で喋っちゃったみたいで。\n\n千景: 昼には、商店街中の人が知ってた。\n\n湊: （栞は、まだ誰にも言ってないと言っていた）\n\n湊: （おかみさんにも、花屋にも、言っていなかった。自分で言うつもりだったんだろう）\n\n千景: さっき、魚屋さんの前で、あの子がいろんな人に囲まれてるの見た。「寂しくなるねえ」って。\n\n千景: あの子、ずっと「はい」しか言ってなかった。\n\n湊: ……。\n\n千景: ごめん。あたしが悪い。\n\n湊: 話したの、俺だから。\n\n千景: それでも。\n\n[label s07_confess]\n\n[show chikage normal]\n\n千景: でね。本題。\n\n湊: 今のが本題じゃないのかよ。\n\n千景: 違うよ。\n\n湊: （千景は防波堤の縁に立って、海のほうを向いた）\n\n[show chikage sad]\n\n千景: あたしさ、ずっと前から湊のこと好きだったよ。\n\n湊: （波の音が、急に大きく聞こえた）\n\n千景: 亀の頃から。たぶん。\n\n湊: ……。\n\n千景: 返事が欲しくて言ったんじゃない。言わないまま湊がどっか行っちゃうの、やだなって思っただけ。\n\n[show chikage normal]\n\n千景: で、聞きたいのはひとつだけ。\n\n千景: 湊、あの子のこと見てるの？ それとも、謎を追ってるだけ？\n\n湊: どういう意味。\n\n千景: あの店の謎が解けたら、湊はたぶん満足するよ。亀のときみたいに。\n\n千景: でも、あの子は満足しないと思う。店がなくなって、お母さんのことがわかって、そのあともずっと、あの子の毎日は続くんだから。\n\n千景: それ、わかってて隣にいるならいい。わかってないなら、もうやめときな。\n\n湊: （千景の声は、怒っても泣いてもいなかった。それがいちばん、こたえた）\n\n[choice]\n- 礼を言って、自分の気持ちは栞にあると伝える -> choice07_a\n- 「今は答えられない」 -> choice07_b\n[/choice]\n\n[label choice07_a]\n[flag chose_shiori = 1]\n\n湊: ありがとう、千景。\n\n[show chikage surprised]\n\n千景: ……え、そこでお礼？\n\n湊: 言ってくれて。ずっと見ててくれて。\n\n湊: でも、俺は栞のことが気になってる。謎だけじゃなくて。\n\n湊: 手紙のことが全部わかっても、たぶん、店に行くと思う。箱詰め、まだ終わってないし。\n\n[show chikage smile]\n\n千景: 箱詰めって。\n\n湊: 本気だよ。\n\n千景: 知ってた。顔に書いてあるもん。\n\n[show chikage sad]\n\n千景: ……知ってたけど、聞きたかったの。\n\n湊: うん。\n\n千景: じゃあ、行きなよ。\n\n[show chikage smile]\n\n千景: 亀みたいにしたら、あたしが川に投げに行くからね。湊を。\n\n[jump scene07_end]\n\n[label choice07_b]\n[flag answer_later = 1]\n\n湊: ……今は、答えられない。\n\n[show chikage pout]\n\n千景: ずるいなあ。\n\n湊: ごめん。\n\n千景: 謝るとこでもないよ。\n\n湊: 栞のことも、千景のことも、適当に答えたくない。\n\n[show chikage normal]\n\n千景: ……ふーん。\n\n千景: 湊が「適当に答えたくない」とか言うの、初めて聞いた。\n\n湊: そうか？\n\n千景: そうだよ。いっつも「別に」で終わらせるじゃん。\n\n[show chikage smile]\n\n千景: じゃあ、待っててあげる。でも、あの子の手紙のほうは待たせちゃだめだよ。\n\n[label scene07_end]\n\n[se waves]\n\n湊: （千景は手を振って、来た道を戻っていった）\n\n湊: （夕日が沈む前に、店に行こうと思った）\n\n[bgm stop]\n[bg black]\n","scenes/ja/scene08.md":"# Scene 08 手紙\n\n[bg shop_night]\n[bgm bgm_rain]\n[se door_bell]\n\n湊: （店の灯りはついていた。札は「準備中」のまま）\n\n[if told_chikage -> s08_hurt]\n\n[show shiori normal]\n\n栞: 来ると思ってました。\n\n湊: 箱、まだ残ってるから。\n\n栞: それもあります。\n\n[jump s08_open]\n\n[label s08_hurt]\n\n[show shiori cold]\n\n栞: ……今日は、もう閉めてます。\n\n湊: 聞いた。商店街のこと。\n\n栞: そうですか。\n\n湊: 千景が、母親に話して、それで広まったって。俺が千景に手紙の話をしたから。ごめん。\n\n[show shiori sad]\n\n栞: 閉店のことは、言ってないんですよね。\n\n湊: 言ってない。でも、きっかけは俺だ。\n\n栞: ……おかみさんに、泣かれました。「なんで言ってくれなかったの」って。\n\n栞: 自分で言いたかったんです。最後のお客さんひとりずつに、ちゃんと。\n\n湊: うん。\n\n栞: 怒ってます。\n\n湊: うん。\n\n[show shiori normal]\n\n栞: でも、篠宮くんに怒っても、仕方ないことも、わかってます。\n\n栞: ……入ってください。濡れますよ。\n\n[label s08_open]\n\n[if trust_shiori < 2 -> s08_alone]\n\n[show shiori normal]\n\n栞: 開けます。約束したので。\n\n湊: （栞はカウンターにペーパーナイフを置いて、深呼吸をひとつした）\n\n[jump s08_read]\n\n[label s08_alone]\n\n[show shiori normal]\n\n栞: 昨日の夜、ひとりで考えました。\n\n栞: 結局、祖父に読む前に、誰かが中身を知らないといけない。祖父、目が悪いので。\n\n栞: ……見てるだけでいいです。読むのは私なので。\n\n[label s08_read]\n\n[se paper]\n\n湊: （封が切られる音が、思ったより大きく響いた）\n\n湊: （中には、便箋が二枚。一枚は古くて、端が茶色くなっている。もう一枚は、それより新しい）\n\n[bg letter_cg]\n[bgm bgm_memory]\n\n栞: 「お父さんへ」\n\n栞: 「この手紙は、高校三年の冬に書きました。出すつもりで書いて、出せなかった手紙です」\n\n栞: 「お父さんとお母さんが別れて、私がお母さんについていって、水瀬の名字になって。それでもこの町の高校に通うって決めたのは、たぶん、この店があったからです」\n\n栞: 「図書室の係を引き受けたのも、本当は、店に来る口実がほしかったからです。お父さんは気づいていたと思うけど」\n\n栞: 「窓際の机で、いつも何か書いてごめんなさい。本を読まずに、ノートばかり広げて。『本を大事にしない子だ』って言われても、仕方ないです」\n\n湊: （栞の声が、一瞬止まった）\n\n栞: 「東京に行きます。お父さんは反対すると思うから、言わずに行きます」\n\n栞: 「でも、この店は、私がいちばん好きな場所です。これだけは、ちゃんと書いておきたかった」\n\n栞: 「雨の日に、ここで雨宿りするのが好きでした」\n\n[se paper]\n\n栞: ……もう一枚。\n\n栞: 「十何年も経って、今さらこれを出します。引き出しの奥から出てきたので」\n\n栞: 「娘がいます。六歳です。本が好きです。私よりずっと大事にします」\n\n栞: 「名前は、栞といいます。この店でつけました」\n\n栞: 「いつか、連れていきます。そのときは、窓際の机を貸してください。遥」\n\n[bg shop_night]\n[bgm bgm_rain]\n[se rain_loop]\n\n[show shiori sad]\n\n湊: （栞は便箋を持ったまま、しばらく動かなかった）\n\n\n栞: ……。\n\n湊: （栞は二枚目の便箋の、自分の名前のところを、親指でそっと押さえていた）\n湊: ……消印、十年前の六月だったよな。\n\n栞: 母が死んだのは、その年の秋です。\n\n湊: ……。\n\n栞: 連れていく、って。\n\n栞: 連れてきてもらえなかったんですね、私。\n\n湊: （何か言わなきゃいけないと思った。何も出てこなかった）\n\n湊: （代わりに、カウンターの端にあったティッシュの箱を、栞の手が届くところまで押した）\n\n[show shiori normal]\n\n栞: ……そういうとこ。\n\n湊: ん。\n\n栞: なんでもないです。\n\n栞: 手紙が届いたの、篠宮さん――お姉さんが本を借りた週ですよね。\n\n湊: 姉ちゃんのカード、同じ週だった。\n\n栞: 祖父、郵便を本の山の上に置く癖があるんです。今でも。\n\n湊: じゃあ、届いた手紙が、返却棚の本に挟まって――\n\n栞: 十年、篠宮家の本棚にいた。\n\n湊: ……姉ちゃんに、一回ちゃんと怒っとく。\n\n[show shiori smile]\n\n栞: お姉さんのせいじゃないですよ。祖父のせいです。\n\n栞: それと、お姉さんが十年返さなかったから、湊くんが返しに来た。\n\n湊: （名前で呼ばれた）\n\n[show shiori normal]\n\n栞: 明日、病院に行きます。祖父にこれを読みます。\n\n栞: ……一緒に来てくれますか。\n\n湊: 行く。\n\n[bgm stop]\n[bg black]\n","scenes/ja/scene09.md":"# Scene 09 病室\n\n[bg hospital_room]\n[bgm bgm_memory]\n\n湊: （翌日の午後。潮見総合病院の四階、いちばん奥の個室）\n\n湊: （窓の外は、珍しく晴れていた）\n\n湊: （ナースステーションの前で、栞は一度立ち止まった）\n\n[show shiori normal]\n\n栞: ……先に言っておきます。祖父、たぶん何も言いません。\n\n湊: うん。\n\n栞: 怒るかもしれません。勝手に開けたので。\n\n湊: そしたら俺も怒られる。\n\n栞: 篠宮くんは関係ないって言われますよ。\n\n湊: じゃあ廊下で待ってる。\n\n栞: ……来てください。中まで。\n\n[hide shiori]\n\n[se door_slide]\n\n[show soichiro normal]\n\n宗一郎: ……誰だ。\n\n[show shiori normal]\n\n栞: 手紙の本を返しに来た人。篠宮くん。\n\n湊: こんにちは。\n\n宗一郎: ……そうか。\n\n湊: （白い髪。丸い眼鏡。灰色のベスト。病院のパジャマの上に、わざわざ着ているらしい）\n\n宗一郎: 篠宮。……上の娘か。十年借りっぱなしの。\n\n湊: 姉です。すみません。\n\n宗一郎: うちは延滞料は取らん。\n\n栞: それ、私も言った。\n\n宗一郎: ……そうか。\n\n湊: （同じ言い方だ、と思った。栞は気づいていないみたいだった）\n\n[show shiori sad]\n\n栞: おじいちゃん。手紙、開けた。\n\n宗一郎: ……。\n\n栞: 読むね。\n\n宗一郎: 頼んどらん。\n\n栞: 頼まれてない。\n\n湊: （宗一郎さんは窓のほうを向いた。でも、耳は塞がなかった）\n\n[se paper]\n\n湊: （栞が、店で読んだのと同じ声で、最初から読んだ）\n\n湊: （「お父さんへ」から、「窓際の机を貸してください」まで）\n\n湊: （途中で一度だけ、宗一郎さんの肩が動いた。「本を大事にしない子だ」のところだった）\n\n[show shiori normal]\n\n栞: ……遥、って。\n\n栞: 知らない字だって、言ったよね。\n\n[show soichiro normal]\n\n宗一郎: ……言った。\n\n栞: なんで。\n\n宗一郎: 知らん字だった。\n\n宗一郎: 高校のときのあれの字は、もっと汚かった。\n\n栞: ……。\n\n宗一郎: 二枚目は、知らん字だ。大人の字だ。十何年、見ておらんかった。\n\n湊: （宗一郎さんは、ゆっくり眼鏡を外して、レンズを拭いた。拭く必要はなさそうだった）\n\n宗一郎: 本を大事にしない子だった。\n\n栞: それ、前も聞いた。\n\n宗一郎: 貸した本に、書きこむ。余白に。台詞の横に、自分の台詞を足す。何度言ってもやめん。\n\n宗一郎: ……あれのせいで、店の本の半分は、売り物にならん。\n\n[show shiori surprised]\n\n栞: 半分って。\n\n宗一郎: 窓際の棚。あれは全部、遥の落書き入りだ。\n\n湊: （箱詰めをしたとき、窓際の棚だけは、栞に「まだいい」と言われて手をつけていなかった）\n\n栞: ……捨てなかったの。\n\n宗一郎: 捨てるか。\n\n[show soichiro gentle]\n\n宗一郎: よく笑う子だった。\n\n宗一郎: 雨が降ると、傘も差さずに走ってきて、店で雨宿りする。帰れと言っても帰らん。わしが傘を貸すと言っても借りん。\n\n宗一郎: 傘を借りたら、雨宿りする理由がなくなる、と言った。\n\n湊: （藍色の、二人入れる傘のことを思い出した）\n\n宗一郎: 店の名前も、あれがつけた。\n\n栞: 久世貸本店でしょ。\n\n宗一郎: 看板はな。あれは「雨宿り」と呼んでおった。「雨宿りの貸本屋」。友達にもそう言っていたらしい。\n\n宗一郎: 図書室の連中まで、そう呼ぶようになった。\n\n[show shiori sad]\n\n栞: ……栞って名前も。\n\n宗一郎: 知らなかった。\n\n宗一郎: 葬式で、お前を引き取るときに、初めて名前を聞いた。……そうか。店でつけたか。\n\n湊: （宗一郎さんは、手紙を受け取らなかった。でも、栞が膝に置いた便箋から、目は離さなかった）\n\n[show soichiro normal]\n\n宗一郎: 篠宮。\n\n湊: はい。\n\n宗一郎: 本は、返しに来るもんだ。\n\n湊: ……はい。\n\n宗一郎: 返しに来たら、また借りていく。そういうふうにできとる。\n\n宗一郎: 店を閉めたら、それができん。\n\n[show shiori surprised]\n\n栞: おじいちゃん。\n\n宗一郎: 栞。お前の好きにしろ。わしはもう、立てん。\n\n宗一郎: ……窓際の棚は、捨てるな。\n\n[se door_slide]\n\n湊: （病室を出ると、廊下の窓から海が見えた）\n\n[show shiori normal]\n\n栞: ……「お前の好きにしろ」って、初めて言われました。\n\n湊: いつもは？\n\n栞: 「勝手にしろ」です。\n\n湊: 似てるけど。\n\n栞: 全然違います。\n\n\n湊: （エレベーターを待つあいだ、栞は便箋を封筒に戻して、それをまたエプロン――じゃなくて、制服のポケットにしまった）\n\n栞: 渡せなかった。\n\n湊: 受け取らなかったな。\n\n栞: ……でも、読んでるあいだ、ずっと聞いてました。\n\n湊: 見てた。肩が動いてた。\n\n[show shiori smile]\n\n栞: 篠宮くん、余計なことばっかり見てますね。\n\n湊: よく言われる。\n\n栞: 誰に。\n\n湊: 千景。\n\n[show shiori normal]\n\n栞: ……そうですか。\n\n湊: （エレベーターのドアが開いた。栞は先に乗って、「閉」のボタンを押す前に、少しだけ待ってくれた）\n\n[bgm stop]\n[bg black]\n","scenes/ja/scene10.md":"# Scene 10 防波堤の夜\n\n[bg seawall_night]\n[bgm bgm_rain]\n[se waves]\n\n湊: （その夜。雨上がりの防波堤）\n\n湊: （梅雨の雲が切れて、潮見町の灯りが水たまりに映っている）\n\n[if answer_later && trust_shiori < 2 -> s10_chikage]\n\n[show shiori normal]\n\n栞: 遅いです。\n\n湊: 呼び出したの、そっちだろ。\n\n栞: 時間、言いましたよね。八時って。\n\n湊: 八時二分。\n\n栞: 遅いです。\n\n湊: （藍色の傘は、閉じたまま防波堤に立てかけてあった）\n\n[show shiori sad]\n\n栞: 窓際の棚の本、帰ってから全部見ました。\n\n湊: 落書き？\n\n栞: 書いてありました。全部の本に。余白に。\n\n栞: 主人公が泣いてる場面の横に、「泣くな」とか。告白の場面の横に、「遅い」とか。\n\n湊: ……そっくりだな。\n\n栞: 何がですか。\n\n湊: いや。\n\n[show shiori normal]\n\n栞: 最後のページに、日付が書いてある本もありました。読み終わった日。雨だった日には、傘の絵。\n\n栞: 母、毎日ここに来てたんですね。\n\n湊: うん。\n\n栞: 私が今、毎日座ってるところに。\n\n[se waves]\n\n湊: （波の音だけが、しばらく続いた）\n\n[show shiori normal]\n\n栞: 祖父、今日、看護師さんに頼んで窓際の棚の本を一冊持ってこさせたそうです。\n\n湊: 読んでた？\n\n栞: 落書きだけ読んでたって。看護師さんが、「おじいちゃん、本を逆さまに持ってた」って笑ってました。\n\n湊: ……ちゃんと読めてるのかな、それ。\n\n栞: 読めてないと思います。たぶん、読まなくても覚えてる。\n\n[show shiori sad]\n\n栞: 篠宮くんがあの日、雨宿りしに来なかったら。\n\n湊: 来てた。傘なかったし。\n\n栞: 本を持ってこなかったら。\n\n湊: 姉ちゃんに押しつけられたし。\n\n栞: ……全部、たまたまですね。\n\n湊: たまたまでいいだろ。手紙は、届いたんだから。\n\n[show shiori normal]\n\n栞: 十年遅れで。\n\n湊: 延滞料、取らないんだろ。\n\n栞: ……取らないです。\n\n\n[show shiori normal]\n\n栞: 店のことも、決めました。明日、話します。\n\n湊: 今じゃなくて？\n\n栞: 今言うと、泣くので。\n\n湊: （冗談なのか本気なのか、やっぱり判断がつかなかった）\n[if chose_shiori && trust_shiori < 2 -> ending_B]\n\n[jump s10_end]\n\n[label s10_chikage]\n\n[show chikage normal]\n\n千景: あ、いた。\n\n湊: 千景。なんでここ。\n\n千景: 湊がいなくなるとき、屋上か図書室か、ここ。言ったでしょ。\n\n湊: （千景の手には、コンビニのビニール袋があった）\n\n[show chikage smile]\n\n千景: 肉まん。半分あげる。\n\n湊: ……ありがと。\n\n千景: で、どうなったの。あの店の話。\n\n湊: 全部わかった。……栞のお母さんの話だった。\n\n千景: そっか。\n\n[if told_chikage -> s10_apology]\n\n[show chikage normal]\n\n千景: 細かいことは聞かないでおく。湊の顔見たら、だいたいわかるし。\n\n[jump s10_end]\n\n[label s10_apology]\n\n[show chikage sad]\n\n千景: あたし今日、あの子に謝りに行ったの。閉店の話、広めちゃったから。\n\n湊: なんて言われた。\n\n千景: 「早瀬さんのおかげで名簿が見られたので」って。\n\n千景: ……いい子だね。腹立つくらい。\n\n[label s10_end]\n\n[ending]\n","scenes/ja/ending_a.md":"# END A 栞のしおり\n\n[label ending_A]\n\n[show shiori normal]\n\n栞: 決めました。\n\n湊: 何を。\n\n栞: 閉店の前に、一日だけ店を開けます。「最後の貸出日」。\n\n栞: 商店街の人にも、昔のお客さんにも、全員に。……今度は、自分で言いに行きます。\n\n湊: 手伝う。\n\n栞: 頼んでません。\n\n湊: 知ってる。\n\n[show shiori smile]\n\n栞: そう言うと思って、もうチラシの枚数、二人分で数えてます。\n\n[bg black]\n[bgm bgm_ending]\n\n湊: （十日後。梅雨の最後の土曜日）\n\n[bg shop_rain]\n[se door_bell]\n[se rain_loop]\n\n湊: （朝から雨だった。栞は「ちょうどいい」と言った）\n\n湊: （店の前に、傘が並んだ。魚屋のおかみさんが干物を差し入れに来て、花屋のお姉さんが「大きくなったねえ」と四回言った）\n\n湊: （姉ちゃんも来た。十年分の延滞を、栞に頭を下げて謝っていた。栞は「うちは取ってないので」と三回言った）\n\n湊: （窓際の机の上には、額に入った便箋が二枚。その横に、落書きだらけの本が並んでいる。「ご自由にお読みください。書きこみ禁止」）\n\n[show chikage smile]\n\n千景: 図書室からも何人か連れてきたよ。提携、二十年ぶりの復活ってことで。\n\n湊: 一日だけだけどな。\n\n千景: 一日でも復活は復活でしょ。\n\n[show chikage normal]\n\n千景: ……湊、ちゃんと隣にいるじゃん。亀にならなくて、えらい。\n\n湊: （千景はそれだけ言って、本の山のほうに行ってしまった）\n\n\n湊: （その日の終わり、栞から電話がかかってきた。いや、正確には、栞が病院にかけた電話を、横で聞いていた）\n\n[se phone_ring]\n\n[show soichiro gentle]\n\n宗一郎: ……何冊出た。\n\n栞: 百二十冊。それと、窓際の棚を見に来た人が、たくさん。\n\n宗一郎: ……そうか。\n\n栞: 魚屋のおかみさんが、「遥ちゃんの字だ」って泣いてた。\n\n宗一郎: あれは昔から、すぐ泣く。\n\n栞: おじいちゃんも、泣いた？\n\n宗一郎: 泣かん。\n\n[show shiori smile]\n\n湊: （電話の向こうで、鼻をかむ音がした。栞は聞こえないふりをした）\n\n[hide soichiro]\n[bg shop_night]\n[bgm bgm_heart]\n\n湊: （七時。最後の客が帰った）\n\n[show shiori normal]\n\n栞: 閉店です。\n\n湊: 閉店だな。\n\n栞: 祖父から電話がありました。「棚は捨てるな」って、また。\n\n湊: 捨てないんだろ。\n\n栞: うちに持って帰ります。窓際の棚ごと。部屋が狭くなります。\n\n[show shiori smile]\n\n栞: それと。\n\n湊: （栞がエプロンのポケットから、一枚の厚紙を出した）\n\n湊: （黄ばんでいない、新しい貸出カード。「久世貸本店」の判子。名前の欄に、丸くも傾いてもいない、まっすぐな字で「篠宮 湊」）\n\n湊: 何これ。\n\n栞: 湊くんの貸出カード。最後の一枚です。\n\n湊: 何を貸してくれんの。\n\n[show shiori blush]\n\n栞: ……それは、自分で考えて。\n\n栞: 返却期限、なしで。\n\n湊: （外の雨が、少し弱くなった）\n\n湊: （傘立てには、藍色の大きな傘が一本だけ残っていた。二人入れるように買った傘だ）\n\n[title END A「栞のしおり」]\n[end]\n","scenes/ja/ending_b.md":"# END B 雨上がり\n\n[label ending_B]\n\n[show shiori normal]\n\n栞: 店、予定どおり月末で閉めます。\n\n湊: ……そっか。\n\n栞: 祖父は「好きにしろ」って言ったけど、好きにしても、ひとりじゃ回せないので。\n\n栞: それに、閉めるって決めたのは私です。決めたことを、ちゃんと最後までやりたい。\n\n湊: うん。\n\n[show shiori sad]\n\n栞: 窓際の棚だけ、うちに持って帰ります。\n\n湊: 落書きの。\n\n栞: 落書きの。\n\n[se waves]\n\n湊: （それから月末まで、何度か店に行った。箱詰めは、最後の日の昼に終わった）\n\n湊: （空っぽになった棚は、思ったより小さかった）\n\n[bg shop_night]\n[bgm bgm_rain]\n\n[show shiori normal]\n\n栞: 四千二百十一冊。全部、箱に入りました。\n\n湊: 半分は俺が詰めた。\n\n栞: 三分の一です。\n\n湊: 数えてたのかよ。\n\n栞: 帳簿つけてたので。\n\n湊: （箱は、古本屋がまとめて引き取っていくらしい。窓際の棚の分だけ、栞の部屋に行く）\n\n[show shiori sad]\n\n栞: 祖父、昨日少しだけ、母の話をしました。\n\n湊: 何て。\n\n栞: 「傘を借りなかった」って。それだけ、三回。\n\n湊: ……。\n\n栞: 三回言うってことは、たぶん、ずっと貸したかったんだと思います。\n\n[show shiori normal]\n\n栞: あの傘、祖父の部屋に置いてきました。病室の、窓のところに。\n\n湊: 退院したら差すかな。\n\n栞: 差さないと思います。雨の日は、外に出ない人なので。\n\n湊: じゃあ、なんで置いてきたの。\n\n栞: ……なんででしょうね。\n\n湊: （最初の日と同じ言い方だった。でも、今度は理由を知っている気がした）\n\n[bg seawall_eve]\n[bgm bgm_ending]\n[se waves]\n\n湊: （閉店の日の夕方。梅雨が明けたらしい、とテレビが言っていた）\n\n[show shiori normal]\n\n栞: 晴れましたね。\n\n湊: 晴れたな。\n\n栞: 雨宿りの理由が、なくなりました。\n\n湊: （藍色の傘は、今日は持っていなかった）\n\n栞: 篠宮くん。\n\n湊: ん。\n\n栞: 本、返しに来てくれて、ありがとうございました。\n\n湊: 姉ちゃんの本だけどな。\n\n[show shiori smile]\n\n栞: 知ってます。\n\n栞: ……また雨が降ったら。\n\n湊: うん。\n\n栞: どこかで、雨宿りしてるかもしれません。\n\n湊: 探す。\n\n栞: 見つからなかったら？\n\n湊: 次の雨の日に、また探す。\n\n[show shiori normal]\n\n栞: ……変な人ですね。\n\n湊: よく言われる。\n\n[se waves]\n\n湊: （栞は手を振らなかった。軽く頭を下げて、防波堤を歩いていった）\n\n湊: （空は、ずっと向こうまで晴れていた）\n\n[title END B「雨上がり」]\n[end]\n","scenes/ja/ending_c.md":"# END C となりの席\n\n[label ending_C]\n\n[show chikage normal]\n\n千景: ねえ、湊。\n\n湊: ん。\n\n千景: あの店の謎、結局、あたしの名簿がなかったら解けなかったでしょ。\n\n湊: ……そうだな。\n\n[show chikage smile]\n\n千景: じゃあ、あたしの勝ち。\n\n湊: 何の勝負だよ。\n\n千景: 知らない。でも勝ち。\n\n[se waves]\n\n湊: （千景は防波堤の縁に座って、肉まんの残りを半分に割った）\n\n[bg black]\n[bgm bgm_ending]\n\n湊: （それから、月末。久世貸本店は閉店した）\n\n湊: （閉店の日、商店街の人がたくさん来たらしい。俺は行かなかった。行っていいのか、わからなかった）\n\n湊: （後日、学校の図書室に段ボールがひとつ届いた。中身は、余白に落書きのある古い本が十冊）\n\n湊: （添えられた便箋には、「提携の最後の貸出です。返却期限、ありません。久世」とだけあった）\n\n湊: （「久世」が、どっちの久世なのかはわからなかった。字はまっすぐで、丸くも、傾いてもいなかった）\n\n湊: （閉店の前の日に一度だけ、商店街で栞とすれ違った。藍色の傘を差していた）\n\n湊: （栞は会釈をして、「お世話になりました」と言った。最初の日と同じ、です・ますだった）\n\n湊: （それでいいんだと思った。思うことにした）\n\n湊: （あの手紙は、宗一郎さんの病室の、窓のところに置いてあるらしい。千景が、魚屋のおかみさん経由で聞いてきた）\n\n[bg library]\n[bgm bgm_daily]\n[se school_chime]\n\n[show chikage normal]\n\n千景: これ、全部書きこみあるよ。図書室の本としてはアウトだね。\n\n湊: 書庫行き？\n\n[show chikage smile]\n\n千景: まさか。カウンターの横に置く。「書きこみ禁止」って貼って。\n\n湊: （千景はいちばん上の一冊を開いて、余白の丸い字を、指でなぞった）\n\n千景: 「遅い」だって。告白の場面の横に。\n\n湊: ……。\n\n[show chikage pout]\n\n千景: なに。\n\n湊: いや。\n\n千景: 言いなよ。\n\n湊: 亀の話。\n\n千景: また？\n\n湊: 返しに行ったの、千景だったよな。俺が飽きたあと。\n\n千景: そうだよ。\n\n湊: あれ、泣いてたのって。亀がかわいそうだったから？\n\n[show chikage surprised]\n\n千景: ……今それ聞く？\n\n湊: 今、答えられる気がしたから。\n\n[show chikage sad]\n\n千景: 湊が、またどっか行っちゃうと思ったから。\n\n湊: （窓の外で、雨が降りはじめていた）\n\n湊: 千景。\n\n[show chikage normal]\n\n千景: なに。\n\n湊: この前の返事。\n\n[show chikage surprised]\n\n千景: ……え、ここで？ 図書室で？\n\n湊: 傘、忘れたから。しばらく帰れない。\n\n湊: 雨宿りのついでに、聞いてほしい。\n\n[show chikage smile]\n\n千景: ……ずるいなあ。\n\n千景: いいよ。となり、座りな。\n\n[title END C「となりの席」]\n[end]\n","scenes/en/scene01.md":"# Scene 01 The Lending Library in the Rain\n\n[bg street_rain]\n[bgm bgm_rain]\n[se rain_heavy]\n\nMinato: (...So much for the weather forecast.)\n\nMinato: (I run with my bag over my head. The shopping arcade's roof gives out halfway down the street.)\n\nMinato: (A row of shuttered shops—and just one with its lights still on.)\n\n[se door_slide]\n[se door_bell]\n[bg shop_rain]\n[se rain_loop]\n\nMinato: Sorry, just for a minute—\n\n[show shiori cold]\n\nShiori: We close at seven.\n\nMinato: Oh, I'm just getting out of the rain. I'll be quick.\n\nShiori: ...The umbrella stand is over there. Please don't touch the shelves while you're wet.\n\nMinato: (I don't have an umbrella. I decided not to mention it.)\n\nMinato: (It smells like old paper. Books are packed all the way to the ceiling, every spine faded by the sun.)\n\nMinato: Is this a bookstore?\n\n[show shiori normal]\n\nShiori: It's a lending library.\n\nMinato: A lending library.\n\nShiori: You borrow a book, read it, and bring it back.\n\nMinato: ...Ah.\n\nMinato: (Come to think of it—I dig through my bag. The book my sister shoved at me this morning.)\n\nMinato: I think this is yours. My sister borrowed it ages ago and forgot to return it.\n\n[show shiori surprised]\n\nShiori: ...\"Kuze Lending Library.\" Yes, it's ours.\n\nShiori: The checkout date is ten years ago, though.\n\nMinato: Sorry. Is there, like, a late fee...?\n\nShiori: We don't charge anything like that.\n\n[se book_drop]\n\nMinato: Oh.\n\nMinato: (The book slips from Shiori's hand as she takes it.)\n\n[se paper]\n\nMinato: (A white envelope slides out from between the pages.)\n\nMinato: Something was tucked inside.\n\n[show shiori normal]\n\nShiori: \"To Mr. Kuze\"...\n\nMinato: The postmark's from ten years ago too.\n\nShiori: It's never been opened.\n\nMinato: (The handwriting on the address was round, leaning slightly to the right.)\n\nMinato: Mr. Kuze—is that someone from the shop?\n\nShiori: My grandfather.\n\nMinato: So it's a letter for your grandpa—\n\n[show shiori cold]\n\nShiori: My grandfather isn't here right now.\n\nMinato: (The way she said it meant: don't ask anything more.)\n\nMinato: (Only the sound of the rain goes on.)\n\n[choice]\n- \"Want to open it?\" -> choice01_a\n- \"You should give it to your grandpa.\" -> choice01_b\n[/choice]\n\n[label choice01_a]\n\nMinato: Want to open it?\n\n[show shiori cold]\n\nShiori: It's someone else's letter.\n\nMinato: ...Yeah, you're right. Sorry.\n\nShiori: But...\n\nMinato: Hm?\n\n[show shiori normal]\n\nShiori: ...No. Never mind.\n\n[jump scene01_end]\n\n[label choice01_b]\n[flag trust_shiori +1]\n\nMinato: You should give it to your grandpa. It's been waiting ten years.\n\n[show shiori surprised]\n\nShiori: You mean the letter's the one that's been waiting?\n\nMinato: Maybe both of them?\n\n[show shiori normal]\n\nShiori: ...You're a strange person.\n\nMinato: I get that a lot.\n\n[jump scene01_end]\n\n[label scene01_end]\n\n[se rain_loop]\n\nMinato: (The rain's letting up.)\n\nMinato: Well, I'll get going. Glad I could return the book.\n\nShiori: Um.\n\n[show shiori sad]\n\nShiori: This shop is closing at the end of the month.\n\nMinato: Huh?\n\nShiori: I haven't told anyone yet. ...So please don't tell anyone.\n\nMinato: Why tell me, then?\n\nShiori: I wonder why.\n\n[show shiori normal]\n\nShiori: Maybe because you're the first person in ten years to come back and return a book.\n\n[se door_bell]\n\nMinato: (Outside, a thin rain was still falling.)\n\nMinato: (When I looked back, through the glass door, she was holding the envelope up to the light.)\n\n[bgm stop]\n[bg black]\n","scenes/en/scene02.md":"# Scene 02 The Next Morning: Classroom to Library\n\n[bg library]\n[bgm bgm_daily]\n[se school_chime]\n\nMinato: (The next morning. The rain had stopped sometime during the night.)\n\nMinato: (From first period to fourth, almost nothing on the blackboard sank in.)\n\nMinato: (Round handwriting. An address slanting to the right. A postmark from ten years ago.)\n\nMinato: (At lunch, I found myself in the school library. Nobody talks to you here.)\n\n[show chikage normal]\n\nChikage: Found you.\n\nMinato: ...How'd you know?\n\nChikage: When you vanish at lunch, it's either here or the roof. And the roof's soaked today.\n\nMinato: What are you, a detective?\n\nChikage: Library committee. I've got counter duty today.\n\nMinato: (Chikage leaned on the counter and started working through a pile of returned books.)\n\n[show chikage smile]\n\nChikage: So?\n\nMinato: \"So\" what?\n\nChikage: It's written all over your face. You've had that thinking face on since this morning.\n\nMinato: Not really. I was thinking about the math quiz.\n\nChikage: You haven't worried about a quiz once since elementary school.\n\nMinato: ...\n\nChikage: See?\n\nMinato: (I couldn't argue. I've known Chikage since kindergarten, and lying to her has never once worked.)\n\n[show chikage normal]\n\nChikage: Oh, right. You live over by the shopping arcade, don't you?\n\nMinato: Behind it.\n\nChikage: Do you know \"Kuze Lending Library\"? The old place in the same row as the fish shop.\n\nMinato: (My hands stopped.)\n\nMinato: ...Yeah, I know it.\n\nChikage: I was sorting the stacks and found an old ledger. Apparently this library and that shop used to have a partnership.\n\nMinato: A partnership?\n\nChikage: Looks like they'd borrow books we didn't have from that shop and lend them out to students. It was a long time ago, though. Even the teacher only remembered, like, \"Oh, right, that was a thing.\"\n\nMinato: Huh.\n\n[show chikage surprised]\n\nChikage: ...That \"huh\" sounded weird.\n\nMinato: It didn't.\n\nChikage: It did. When you're really not interested, you go \"hmm.\"\n\nMinato: (She's got me figured out down to that?)\n\n[show chikage normal]\n\nChikage: What? Did something happen with that shop?\n\nMinato: (I thought about the envelope from yesterday. And about the shop closing.)\n\nMinato: (She asked me not to tell anyone about the closing. About the letter—she didn't say anything.)\n\n[choice]\n- Tell Chikage about the letter -> choice02_a\n- Dodge the question -> choice02_b\n[/choice]\n\n[label choice02_a]\n[flag told_chikage = 1]\n\nMinato: ...Yesterday I ducked into that shop to get out of the rain.\n\nMinato: I was returning a book my sister kept for ten years. And a letter fell out of it.\n\n[show chikage surprised]\n\nChikage: A letter?\n\nMinato: Still sealed. Addressed to the old man who runs the shop, postmarked ten years ago.\n\nChikage: Wait, what? That's basically a mystery case.\n\nMinato: It's not a case.\n\nChikage: A letter that took ten years to arrive? That's totally a case.\n\n[show chikage smile]\n\nChikage: So who's it from?\n\nMinato: Didn't say. The handwriting was round, that's all.\n\nChikage: Round handwriting. Like, girly?\n\nMinato: Probably.\n\nChikage: Hmm.\n\nMinato: ...What?\n\nChikage: Nothing? Was there someone minding the shop?\n\nMinato: Yeah. His granddaughter.\n\nChikage: Is she cute?\n\nMinato: That's got nothing to do with it.\n\nChikage: You're not denying it.\n\nMinato: (For the last ten minutes of lunch, Chikage flipped through the ledger, grinning the whole time.)\n\n[show chikage normal]\n\nChikage: I'll dig a little more into the partnership records for you. I'll let you know if I find anything.\n\nMinato: ...Thanks. That helps.\n\n[jump scene02_end]\n\n[label choice02_b]\n\nMinato: My sister used to borrow books there, apparently. That's all.\n\n[show chikage pout]\n\nChikage: That's all?\n\nMinato: That's all.\n\nChikage: ...Fine, whatever.\n\nMinato: (Chikage started scanning the barcodes on the returns a little harder than usual.)\n\n[show chikage normal]\n\nChikage: If you don't want to tell me, that's fine. But you're bad at keeping secrets, you know.\n\nMinato: I know.\n\nChikage: Then quit it.\n\nMinato: (I didn't answer that.)\n\n[label scene02_end]\n\n[se school_chime]\n\nMinato: (The warning bell rang. Chikage hugged her pile of books and disappeared into the stacks.)\n\nMinato: (Outside the window, the clouds were gathering again.)\n\nMinato: (After school, I'd go to that shop again. I could figure out a reason later.)\n\n[bg black]\n[se door_slide]\n\nMinato: (On the way home, I texted my sister: \"Why didn't you return that book ten years ago?\")\n\nMinato: (She replied three minutes later. \"I thought I did.\" \"Something happen?\")\n\nMinato: (I typed \"there was an envelope in it,\" then deleted it. I sent \"nothing.\")\n\nMinato: (\"Is the old man there doing okay? He was scary but really kind.\")\n\nMinato: (I left it on read and stared at the screen for a while.)\n\n[bgm stop]\n[bg black]\n","scenes/en/scene03.md":"# Scene 03 The Lending Library, Second Visit\n\n[bg street_rain]\n[bgm bgm_rain]\n[se rain_loop]\n\nMinato: (After school. Right on forecast, it started raining again.)\n\nMinato: (Today I'd bought an umbrella at the convenience store. One of the clear plastic ones.)\n\n[se door_slide]\n[se door_bell]\n[bg shop_rain]\n\n[show shiori surprised]\n\nShiori: ...\n\nMinato: Hey.\n\n[show shiori cold]\n\nShiori: Did you keep other books, too?\n\nMinato: No.\n\nShiori: Then are you sheltering from the rain? You have an umbrella.\n\nMinato: I do.\n\nShiori: ...\n\nMinato: I thought I'd help. If you're closing, there must be packing and stuff.\n\n[show shiori normal]\n\nShiori: I did not ask you to.\n\nMinato: I know.\n\nMinato: (Shiori was quiet for a moment, then pointed to the back of the shop.)\n\nShiori: The back shelves, third row down and below. Everything goes into boxes. Spines facing up, in numerical order.\n\nMinato: Got it.\n\nShiori: Please do not touch them with wet hands.\n\nMinato: I dried them.\n\nShiori: And the umbrella goes outside.\n\nMinato: ...Yes, ma'am.\n\n[se footsteps_wet]\n\nMinato: (The work was plainer than I expected. Pull a book, check the number, put it in the box. Over and over.)\n\nMinato: (Shiori sat by the register, silently writing in a ledger. Just the sound of her pen and the rain.)\n\nMinato: What are these numbers?\n\nShiori: The order the books came in. My grandfather wrote every one of them by hand.\n\nMinato: Every one?\n\nShiori: Every one. Four thousand two hundred and eleven books.\n\nMinato: That's amazing.\n\nShiori: His handwriting is terrible, so about half of them are unreadable.\n\nMinato: (I couldn't tell whether that was a joke.)\n\nMinato: Your grandpa's not here today?\n\n[show shiori sad]\n\nShiori: He is in the hospital. Since spring.\n\nMinato: ...I see.\n\nShiori: His heart. The surgery is done, and it is not life or death. But he cannot work the shop anymore.\n\nMinato: So that's why you're closing.\n\nShiori: I cannot run it on my own.\n\nMinato: (The sound of the pen had stopped.)\n\nShiori: I took the letter to the hospital yesterday.\n\nMinato: Did you give it to him?\n\nShiori: I showed it to him. Only the address.\n\nMinato: What did he say?\n\nShiori: \"I don't know that handwriting.\"\n\nMinato: ...\n\nShiori: That is all he said. Then he turned toward the window.\n\n[show shiori normal]\n\nShiori: So I still have it.\n\nMinato: (Shiori pulled just the corner of the envelope out of her apron pocket to show me.)\n\nMinato: Then why not find out who wrote it?\n\nShiori: And what would that accomplish?\n\nMinato: If it turns out he does know the handwriting, he might take it.\n\n[show shiori surprised]\n\nShiori: ...\n\nMinato: If it's postmarked ten years ago, maybe it's someone who came to the shop back then. Don't you have records or something?\n\nShiori: There are checkout cards. We kept the card for every book that was returned.\n\nMinato: Every one?\n\nShiori: My grandfather is not the type to throw things away.\n\n[se paper]\n\nMinato: (Shiori brought three shoeboxes from the back. They were crammed with yellowed cardstock cards.)\n\nMinato: (Dates, names, and return stamps. The bundle from ten years ago alone had over a hundred.)\n\nShiori: I will narrow it down to the rainy season ten years ago. The postmark is June.\n\nMinato: Wonder if my sister's name is in there.\n\nShiori: Shinomiya. ...Here. The same week.\n\nMinato: (My sister's handwriting was as awful then as it is now.)\n\nMinato: (We split the rest of the cards between us and started flipping through them.)\n\n[choice]\n- Check the back of each checkout card -> choice03_a\n- Take another close look at the handwriting on the envelope -> choice03_b\n[/choice]\n\n[label choice03_a]\n[flag found_stamp = 1]\n\nMinato: (Just looking at the names on the front wasn't getting us anywhere. I flipped one over.)\n\nMinato: (Most were blank. But a few had a faint, round vermilion stamp on them.)\n\nMinato: What's this stamp?\n\n[show shiori surprised]\n\nShiori: ...\"Shiomi High School Library.\"\n\nMinato: That's my school.\n\nShiori: They had a partnership. The shop used to lend books to the school library.\n\nMinato: I heard about that today.\n\nShiori: From whom?\n\nMinato: A friend on the library committee.\n\nMinato: (I lined up the stamped cards. On one of the old ones, dated much further back, was handwriting I recognized.)\n\nMinato: This one.\n\nShiori: \"School library order — in charge:\" ...The name is smudged.\n\nMinato: But this handwriting.\n\n[show shiori normal]\n\nShiori: ...Round. Slanting to the right.\n\nMinato: Same as the envelope.\n\nShiori: This card is more than twenty years old.\n\nMinato: Yeah.\n\nShiori: The person who wrote a letter ten years ago came here even before that...?\n\nMinato: And as the school library's contact, no less.\n\nMinato: (Shiori laid the card next to the envelope and looked at them for a long time.)\n\n[jump scene03_end]\n\n[label choice03_b]\n\nMinato: Let me see the envelope for a sec.\n\nShiori: Do not open it.\n\nMinato: I won't.\n\nMinato: (The address: \"Mr. Kuze.\" Short flicks on the strokes, all round. The final dot weirdly big.)\n\nMinato: I think it's a woman's handwriting. Someone young.\n\n[show shiori normal]\n\nShiori: Is that so?\n\nMinato: One of my sister's friends wrote like this. The type who draws hearts in the margins of her notebook.\n\nShiori: That is a stereotype.\n\nMinato: Probably.\n\nMinato: (In the end, the bundles of cards gave us no more clues than that.)\n\n[label scene03_end]\n\n[se rain_loop]\n\nMinato: (Before I knew it, it had gotten dark outside.)\n\n[show shiori normal]\n\nShiori: It is seven o'clock.\n\nMinato: Closing time?\n\nShiori: Closing time.\n\nMinato: Can I come back tomorrow?\n\nShiori: ...There are still boxes left.\n\nMinato: Is that a yes?\n\n[show shiori cold]\n\nShiori: As long as you do not touch anything with wet hands.\n\n[bgm stop]\n[bg black]\n","scenes/en/scene04.md":"# Scene 04 Rain on the Shopping Street\n\n[bg street_rain]\n[bgm bgm_mystery]\n[se rain_loop]\n\nMinato: (Day three. The boxes were half done.)\n\nMinato: (That day, Shiori flipped the shop sign to \"Closed\" and took off her apron.)\n\n[show shiori normal]\n\nShiori: We are going to ask around.\n\nMinato: Ask around.\n\nShiori: People who have been on this street for ten years might remember our regulars.\n\nMinato: Like a cop show.\n\nShiori: A cop show would have more people in it.\n\nMinato: (True. There were more shutters than shoppers.)\n\nMinato: (Shiori opened an old indigo umbrella. It was huge, and one of its ribs was bent.)\n\n[se umbrella_open]\n\nShiori: It is my grandfather's.\n\nMinato: It's big.\n\nShiori: Apparently he bought it so two people could fit. I do not know who he meant to share it with.\n\nMinato: (I put up my clear convenience-store umbrella and walked beside her.)\n\n[se footsteps_wet]\n\nMinato: (The old man at the futon shop remembered the lending library, but not its customers.)\n\nMinato: (The tobacco shop had changed owners five years ago.)\n\nMinato: (The woman at the flower shop looked at Shiori and said \"Look how big you've gotten!\" three times.)\n\n[show shiori sad]\n\nShiori: ...Nothing so far.\n\nMinato: You grew up here, Shiori?\n\nShiori: Since I was six.\n\nMinato: And before that?\n\nShiori: Tokyo. I do not remember much.\n\nMinato: (I didn't ask anything more.)\n\n[show shiori normal]\n\nShiori: One more place.\n\nMinato: Where?\n\nShiori: The fish shop. The owner's wife knows everything about this street.\n\n[se footsteps_wet]\n\nFishmonger's wife: Well, if it isn't Shiori! It's been ages! How's your grandpa?\n\nShiori: He is fine. Bored.\n\nFishmonger's wife: Good to hear. And who's this? Your boyfriend?\n\n[show shiori cold]\n\nShiori: No.\n\nMinato: No.\n\nFishmonger's wife: My, you two are in sync.\n\nMinato: (Shiori moved a little away from me.)\n\nShiori: About ten years ago, do you remember a customer who came to our shop a lot? A woman.\n\nFishmonger's wife: Ten years ago, hmm... We still had a fair number of customers back then.\n\nFishmonger's wife: Oh, but.\n\nShiori: But?\n\nFishmonger's wife: Not ten years ago—earlier. Way, way back. There was a girl who was always writing something in there. A high schooler.\n\nMinato: Writing?\n\nFishmonger's wife: You know that little desk by the window? She'd sit there, and instead of reading, she'd be writing in a notebook. Soichiro would just watch her with that scary face, but he never chased her out.\n\nShiori: ...What was her name?\n\nFishmonger's wife: Oh, I couldn't tell you her name. She laughed a lot, that girl. That's the only time I ever saw Soichiro talk so much.\n\n[show shiori surprised]\n\nShiori: My grandfather... talked?\n\nFishmonger's wife: He did! Can't picture it now, can you?\n\nFishmonger's wife: Then one day she stopped coming. Graduated, I suppose. Soichiro was down in the dumps for a while.\n\nFishmonger's wife: ...Oh, listen to me, going on about the old days. Here, take this. For your grandpa.\n\nMinato: (A plastic bag of dried horse mackerel was pushed into Shiori's arms.)\n\n[bgm bgm_rain]\n\nMinato: (On the way back, the rain got heavier.)\n\n[se rain_heavy]\n\nMinato: (My clear umbrella flapped and bucked in the wind.)\n\n[se thunder_far]\n\nMinato: Ah.\n\nMinato: (Two ribs flipped inside out at once.)\n\n[show shiori normal]\n\nShiori: ...Well, it was three hundred yen.\n\nMinato: Five hundred.\n\nShiori: Same thing.\n\nMinato: (Without a word, Shiori tilted the indigo umbrella a little toward me.)\n\nMinato: (An umbrella bought for two. And two of us did fit. Barely.)\n\nMinato: (Keeping our shoulders from touching was harder than I thought.)\n\n[choice]\n- \"I'll hold the umbrella.\" -> choice04_a\n- Walk on without saying anything -> choice04_b\n[/choice]\n\n[label choice04_a]\n[flag trust_shiori +1]\n\nMinato: I'll hold the umbrella.\n\n[show shiori surprised]\n\nShiori: Huh?\n\nMinato: Your wrist's all bent. You'll get tired holding it like that.\n\nShiori: ...Just because you are tall.\n\nMinato: If the short one holds it, the ribs poke the tall one in the head.\n\n[show shiori smile]\n\nShiori: Heh.\n\nMinato: (I felt like it was the first time I'd seen her really laugh.)\n\nShiori: Then, please.\n\nMinato: (The handle was colder than I expected.)\n\nMinato: (Shiori hugged the bag of fish to her chest and stepped half a step closer.)\n\nShiori: Your shoulder is getting wet, Shinomiya.\n\nMinato: Comes with the job of umbrella holder.\n\nShiori: Where do you learn things like that?\n\nMinato: My sister.\n\nShiori: Your sister teaches you a lot. Even if she does not return books.\n\n[jump scene04_end]\n\n[label choice04_b]\n\nMinato: (I started to say something, then didn't.)\n\nMinato: (Shiori kept her eyes forward, gripping the umbrella handle with both hands.)\n\nMinato: (Every now and then the bag of fish bumped against my arm.)\n\n[show shiori normal]\n\nShiori: ...\n\nMinato: ...\n\nMinato: (It was a silence that wasn't quite awkward.)\n\n[label scene04_end]\n\n[bg shop_rain]\n[se door_bell]\n\nMinato: (When we got to the shop, Shiori closed the umbrella and tried to straighten the bent rib with her fingers. It didn't work.)\n\n[show shiori normal]\n\nShiori: \"She laughed a lot.\"\n\nMinato: Yeah.\n\nShiori: I cannot imagine words like that coming out of my grandfather's mouth.\n\nMinato: But she said she saw it.\n\nShiori: ...Maybe I do not know anything about my grandfather.\n\n[bgm stop]\n[bg black]\n","scenes/en/scene05.md":"# Scene 05 Old Records in the School Library\n\n[bg library]\n[bgm bgm_mystery]\n[se school_chime]\n\nMinato: (The next day after school. In the back of the library, in front of the stacks room that's usually locked.)\n\n[show chikage normal]\n\nChikage: Here. The old library committee rosters. About twenty years' worth.\n\nMinato: ...How'd you know I was coming?\n\n[if told_chikage -> s05_told]\n\nChikage: Obviously. You were walking down the shopping street under an umbrella yesterday, weren't you? With the lending library girl.\n\nMinato: You were watching?\n\n[show chikage pout]\n\nChikage: I happened to see. In front of the fish shop. ...So what are you digging into about that shop? You've been acting weird ever since I mentioned the partnership.\n\nMinato: (No point dodging it now.)\n\nMinato: ...I'm looking for someone who used to come to that shop. Someone who might've been the library's contact.\n\nChikage: Hmm. And that's something you can't tell me about?\n\nMinato: Not right now.\n\n[show chikage normal]\n\nChikage: ...Eh, fine. If you're looking at the rosters, you'll need the key to the stacks. I'll open it for you.\n\n[jump s05_search]\n\n[label s05_told]\n\nChikage: I told you I'd look into it, didn't I?\n\n[show chikage smile]\n\nChikage: Also, I invited one more person today.\n\nMinato: Huh?\n\n[se door_slide]\n\n[show shiori normal]\n\nShiori: ...Excuse me.\n\nMinato: Shiori?\n\nShiori: Hayase called the shop. She said, \"I'm pulling out the rosters, come over.\"\n\nChikage: The shop's phone number was in the ledger.\n\nMinato: You just went ahead and...\n\nChikage: You're the one who said you were looking for whoever wrote the letter. It's faster with the person herself here.\n\n[show shiori cold]\n\nShiori: I am not \"the person herself.\" I just mind the shop.\n\nChikage: Okay, okay. Nice to meet you, Kuze. I'm Chikage Hayase. Minato and I go back to kindergarten.\n\nShiori: ...Kuze.\n\nMinato: (Chikage was all smiles. Shiori, in another school's uniform, looked a little out of place.)\n\n[label s05_search]\n\n[se paper]\n\nMinato: (The rosters were thin files bound by school year. Handwritten names, classes, assigned weekdays.)\n\nMinato: (Ten to fifteen people per year. Twenty years' worth meant over two hundred.)\n\n[if found_stamp -> s05_found]\n\nMinato: All we've got is \"a girl with round handwriting who was in charge\"...\n\n[show chikage normal]\n\nChikage: There are a hundred girls in here alone.\n\nMinato: Yeah.\n\nChikage: If there was someone in charge of the partnership, isn't there a record of that?\n\nMinato: There was nothing left at the shop.\n\nChikage: Hmm...\n\nMinato: (I flipped through file after file. Plenty of names in round handwriting. None of them conclusive.)\n\nMinato: (Just one page caught my eye. A school year from twenty-some years ago. Next to \"Lending library (Kuze)\" in the duty column, there was a single name.)\n\nMinato: (An ink stain had spilled over that name. Only the last character was legible.)\n\nMinato: \"Haruka\"...?\n\nChikage: Haruka?\n\nMinato: Can't read the surname.\n\nChikage: There are a lot of girls named Haruka.\n\nMinato: Yeah.\n\nMinato: (I copied it into my notes anyway. Haruka. In charge of the lending library. Twenty-some years ago.)\n\n[jump s05_end]\n\n[label s05_found]\n\nMinato: The card with the stamp was dated autumn, twenty-two years ago.\n\nMinato: (I pulled out the file for that year.)\n\n[show chikage surprised]\n\nChikage: Oh, here. The duty column says \"Lending library (Kuze).\"\n\nMinato: So instead of a weekday shift, there was a contact person for the shop.\n\nChikage: And only one.\n\nMinato: (I read the name. Round letters, slanting slightly right, in her own hand.)\n\nMinato: \"Haruka Minase.\"\n\n[if told_chikage -> s05_shiori_hears]\n\nChikage: Minase, Haruka. ...Someone you know?\n\nMinato: No.\n\nMinato: (But I know this handwriting. It's the same as the envelope.)\n\nMinato: (I have to tell Shiori this name.)\n\n[jump s05_end]\n\n[label s05_shiori_hears]\n\n[show shiori surprised]\n\nShiori: ...\n\nMinato: Shiori?\n\nShiori: Minase was my mother's surname before she married.\n\n[show chikage surprised]\n\nChikage: What?\n\nShiori: Haruka is my mother's name.\n\nMinato: (The air in the stacks suddenly felt colder.)\n\n[show shiori sad]\n\nShiori: But my mother was supposed to be from Tokyo. I have never heard that she lived in this town.\n\nChikage: ...I'm sorry. I invited you without really thinking.\n\nShiori: No.\n\nShiori: If you had not invited me, I would never have known.\n\n[label s05_end]\n\n[se school_chime]\n\n[show chikage normal]\n\nChikage: That's the final bell. I'm locking up the stacks.\n\nMinato: Yeah.\n\nChikage: Hey, Minato.\n\nMinato: Hm?\n\n[show chikage sad]\n\nChikage: Never mind. ...I need to talk to you tomorrow, so give me a little time.\n\nMinato: (With that, Chikage twirled the key around her finger and walked out ahead of me.)\n\n[bgm stop]\n[bg black]\n","scenes/en/scene06.md":"# Scene 06 The Shrine Steps\n\n[bg shrine_steps]\n[bgm bgm_memory]\n[se rain_loop]\n\nMinato: (That night. When I passed the shop, its lights were off.)\n\nMinato: (For no real reason, I walked up the hill to the shrine. Halfway up the steps, an indigo umbrella sat open.)\n\n[show shiori normal]\n\nShiori: ...Why are you here?\n\nMinato: I could ask you the same.\n\nShiori: When I am in the shop, all I see are boxes.\n\nMinato: (Under the umbrella, Shiori sat hugging her knees. The rain had thinned to almost a mist.)\n\nMinato: Mind if I sit?\n\nShiori: It is wet there.\n\nMinato: I'm already wet.\n\n[se rain_loop]\n\nMinato: (For a while, neither of us spoke. Down below, the streetlights of the shopping arcade blurred one by one.)\n\n[show shiori sad]\n\nShiori: My mother died when I was six.\n\nMinato: ...\n\nShiori: Of an illness. In a hospital in Tokyo. After that, my grandfather took me in, and I came here.\n\nShiori: Please do not ask about my father. I do not know much about him either.\n\nMinato: I won't.\n\nShiori: My grandfather has never once talked about my mother. There are no photos. Only her memorial tablet on the altar.\n\nShiori: When I was little, I asked him just once. \"What was my mother like?\"\n\nMinato: What did he say?\n\nShiori: \"She was a girl who didn't take care of books.\"\n\nMinato: (A weird noise almost escaped me.)\n\n[show shiori normal]\n\nShiori: ...This is where you laugh.\n\nMinato: How could I laugh?\n\nShiori: I laughed. Because he would not say anything else. Because that was the only thing I knew about my mother.\n\n[if found_stamp -> s06_know]\n\nMinato: Can I ask your mother's name?\n\nShiori: Haruka.\n\nMinato: (The roster in the school library. The single character left beside the ink stain.)\n\nMinato: ...I saw it in a school roster today. A library committee member from twenty-some years ago who was the contact for the shop. I couldn't read the surname, but the first name was \"Haruka.\"\n\n[show shiori surprised]\n\nShiori: ...\n\nMinato: The girl the fishmonger's wife talked about, writing at the desk by the window. The round handwriting on the envelope. I think they're all the same person.\n\nMinato: I haven't confirmed it. It's just a hunch.\n\nShiori: My mother was from Tokyo.\n\nMinato: Maybe she was here just for high school.\n\nShiori: ...I have never heard anything like that.\n\n[jump s06_choice]\n\n[label s06_know]\n\n[if told_chikage -> s06_know_told]\n\nMinato: I found it in a school roster today. A library committee member who was the contact between the shop and the library twenty-two years ago.\n\nMinato: Someone named \"Haruka Minase.\" The handwriting matched the envelope.\n\n[show shiori surprised]\n\nShiori: ...Minase.\n\nMinato: You know the name?\n\nShiori: It was my mother's surname before she married. And her name was Haruka.\n\nMinato: (I knew it, I thought. I only thought it. I didn't say it.)\n\n[jump s06_after_know]\n\n[label s06_know_told]\n\nShiori: The roster this afternoon. ...I have been thinking about it ever since.\n\nMinato: Yeah.\n\n[label s06_after_know]\n\n[show shiori sad]\n\nShiori: I thought my mother was from Tokyo.\n\nShiori: But in high school, she was in this town. Coming to our shop. Talking with my grandfather.\n\nShiori: And my grandfather said, \"I don't know that handwriting.\"\n\nMinato: ...There's no way he didn't know it.\n\nShiori: There is no way.\n\n[label s06_choice]\n\nMinato: (Shiori took the envelope out of her pocket. Its corners had gone a little soft. She must have handled it again and again these past few days.)\n\n[choice]\n- \"Let's read it together.\" -> choice06_a\n- \"It's your call, Shiori.\" -> choice06_b\n[/choice]\n\n[label choice06_a]\n\nMinato: Let's read it together. If opening it alone is too hard.\n\n[if trust_shiori < 1 -> s06_refuse]\n[flag trust_shiori +1]\n\n[show shiori surprised]\n\nShiori: ...Together.\n\nMinato: It came out of a book I brought in. So I'm at least half responsible, right?\n\nShiori: What kind of logic is that?\n\nMinato: Call it my late fee.\n\n[show shiori smile]\n\nShiori: ...I told you, we don't charge late fees.\n\nMinato: (Her formal tone had slipped a little.)\n\nShiori: Fine, then I'll charge one. Be next to me when I open it.\n\nMinato: Okay.\n\nShiori: Not now. At the shop. I want to read it somewhere properly bright.\n\n[jump scene06_end]\n\n[label choice06_b]\n\nMinato: It's your call, Shiori. Open it or don't.\n\n[if trust_shiori < 1 -> s06_refuse]\n[flag trust_shiori +1]\n\n[show shiori surprised]\n\nShiori: ...Mine?\n\nMinato: It's addressed to your grandpa, but your mom wrote it, right? It's not my decision.\n\nShiori: Do you think I have the right to open my grandfather's letter?\n\nMinato: I think whether you do isn't for me to decide. It's for you.\n\n[show shiori blush]\n\nShiori: You're not playing fair, Minato.\n\nMinato: (The first time she'd called me by my first name. I had a feeling that if I pointed it out, she'd never do it again, so I kept quiet.)\n\nShiori: ...I'll open it. At the shop. Before I read it to my grandfather, I'll read it first.\n\nShiori: I think I've earned at least that much.\n\n[jump scene06_end]\n\n[label s06_refuse]\n\n[show shiori cold]\n\nShiori: ...I cannot open it yet.\n\nMinato: Okay.\n\nShiori: It is not something I will open just because you told me to, Shinomiya.\n\nMinato: (The envelope went back into her pocket.)\n\nMinato: (On the first day, I was the one who asked if she wanted to open it. She probably remembers.)\n\n[show shiori normal]\n\nShiori: But I know whose letter it is now.\n\nShiori: ...For that, thank you.\n\n[label scene06_end]\n\n[se rain_loop]\n\nMinato: (The drizzle stopped. Shiori closed the umbrella and went down the stone steps one at a time.)\n\nMinato: (Halfway down, she looked back just once, started to say something, and didn't.)\n\n[bgm stop]\n[bg black]\n","scenes/en/scene07.md":"# Scene 07 Chikage's Warning\n\n[bg street_rain]\n[bgm bgm_daily]\n[se rain_loop]\n\nMinato: (The next day after school. Chikage was waiting at the school gate.)\n\n[show chikage normal]\n\nChikage: I told you to give me some time, remember?\n\nMinato: You did.\n\nChikage: We can talk while we walk. You're heading to the shopping street anyway, right?\n\nMinato: (She had me there, so I fell in beside her without a word.)\n\n[se footsteps_wet]\n\nChikage: Remember in elementary school, when you brought home a turtle from the river?\n\nMinato: ...I don't.\n\nChikage: You did. You named it, fed it every day, sketched the pattern on its shell.\n\nChikage: Then you got bored after a month, and I was the one who took it back to the river.\n\nMinato: That part I remember. You were crying and yelling at me.\n\n[show chikage pout]\n\nChikage: I wasn't crying.\n\nMinato: You were.\n\nChikage: I was yelling, though.\n\n[bg seawall_eve]\n[bgm bgm_heart]\n[se waves]\n\nMinato: (We came out of the shopping street onto the seawall. The rain had stopped, and evening sun was slanting through a gap in the clouds.)\n\n[show chikage normal]\n\nChikage: You get totally swept up in whatever catches your interest. And once you've figured it out, you move on.\n\nMinato: ...\n\nChikage: I'm not blaming you. I've just been watching you be like that forever.\n\n[if told_chikage -> s07_leak]\n[jump s07_confess]\n\n[label s07_leak]\n\n[show chikage sad]\n\nChikage: And—let me apologize first.\n\nMinato: For what?\n\nChikage: Last night I told my mom about the lending library. The letter, the girl's mom, all of it. I thought it was an interesting story.\n\nChikage: And my mom goes, \"I hear that place is closing soon.\"\n\nMinato: ...Who told her?\n\nChikage: No idea. Maybe someone heard at the hospital. But because I brought it up, my mom ended up talking about it at her part-time job this morning.\n\nChikage: By lunch, the whole shopping street knew.\n\nMinato: (Shiori said she hadn't told anyone yet.)\n\nMinato: (Not the fishmonger's wife, not the flower shop. She must have meant to tell them herself.)\n\nChikage: Just now, in front of the fish shop, I saw her surrounded by people. \"We'll miss you so much.\"\n\nChikage: All she kept saying was \"Yes.\"\n\nMinato: ...\n\nChikage: I'm sorry. It's my fault.\n\nMinato: I'm the one who told you.\n\nChikage: Even so.\n\n[label s07_confess]\n\n[show chikage normal]\n\nChikage: Anyway. The real topic.\n\nMinato: That wasn't the real topic?\n\nChikage: Nope.\n\nMinato: (Chikage stood at the edge of the seawall, facing the sea.)\n\n[show chikage sad]\n\nChikage: I've liked you for a long time, Minato.\n\nMinato: (The sound of the waves suddenly got louder.)\n\nChikage: Since the turtle. Probably.\n\nMinato: ...\n\nChikage: I'm not saying it because I want an answer. I just didn't want you to wander off somewhere without me ever saying it.\n\n[show chikage normal]\n\nChikage: So there's just one thing I want to ask.\n\nChikage: Are you actually looking at her? Or are you just chasing a mystery?\n\nMinato: What do you mean?\n\nChikage: Once you solve the mystery of that shop, you'll probably be satisfied. Like with the turtle.\n\nChikage: But I don't think she will be. The shop will be gone, she'll know about her mom, and her life will just keep going on after that.\n\nChikage: If you're by her side knowing that, fine. If you're not, then you'd better stop.\n\nMinato: (Chikage's voice wasn't angry and it wasn't tearful. That's what hit hardest.)\n\n[choice]\n- Thank her, and tell her your heart is with Shiori -> choice07_a\n- \"I can't answer right now.\" -> choice07_b\n[/choice]\n\n[label choice07_a]\n[flag chose_shiori = 1]\n\nMinato: Thanks, Chikage.\n\n[show chikage surprised]\n\nChikage: ...Wait, you're thanking me?\n\nMinato: For telling me. For watching out for me all this time.\n\nMinato: But I care about Shiori. Not just the mystery.\n\nMinato: Even after I figure out everything about the letter, I'll probably still go to the shop. The boxes aren't done yet.\n\n[show chikage smile]\n\nChikage: The boxes?\n\nMinato: I mean it.\n\nChikage: I know. It's written all over your face.\n\n[show chikage sad]\n\nChikage: ...I knew, but I wanted to hear it.\n\nMinato: Yeah.\n\nChikage: Then go.\n\n[show chikage smile]\n\nChikage: If you pull a turtle on her, I'm throwing you in the river. You, not the turtle.\n\n[jump scene07_end]\n\n[label choice07_b]\n[flag answer_later = 1]\n\nMinato: ...I can't answer right now.\n\n[show chikage pout]\n\nChikage: That's not fair.\n\nMinato: Sorry.\n\nChikage: It's not something to apologize for.\n\nMinato: I don't want to give a half-baked answer. Not about Shiori, and not about you.\n\n[show chikage normal]\n\nChikage: ...Hmm.\n\nChikage: That's the first time I've ever heard you say you don't want to give a half-baked answer.\n\nMinato: Is it?\n\nChikage: It is. You always end things with \"whatever.\"\n\n[show chikage smile]\n\nChikage: Okay, I'll wait. But don't keep her waiting about the letter.\n\n[label scene07_end]\n\n[se waves]\n\nMinato: (Chikage waved and headed back the way we came.)\n\nMinato: (I decided to go to the shop before the sun went down.)\n\n[bgm stop]\n[bg black]\n","scenes/en/scene08.md":"# Scene 08 The Letter\n\n[bg shop_night]\n[bgm bgm_rain]\n[se door_bell]\n\nMinato: (The shop's lights were on. The sign still said \"Closed.\")\n\n[if told_chikage -> s08_hurt]\n\n[show shiori normal]\n\nShiori: I thought you would come.\n\nMinato: There are still boxes left.\n\nShiori: That too.\n\n[jump s08_open]\n\n[label s08_hurt]\n\n[show shiori cold]\n\nShiori: ...We are already closed today.\n\nMinato: I heard. About the shopping street.\n\nShiori: I see.\n\nMinato: Chikage told her mom, and that's how it spread. Because I told Chikage about the letter. I'm sorry.\n\n[show shiori sad]\n\nShiori: You did not tell her about the closing, did you?\n\nMinato: I didn't. But I'm the one who started it.\n\nShiori: ...The fishmonger's wife cried at me. \"Why didn't you tell me?\"\n\nShiori: I wanted to tell them myself. Each of our last customers, one by one, properly.\n\nMinato: Yeah.\n\nShiori: I am angry.\n\nMinato: Yeah.\n\n[show shiori normal]\n\nShiori: But I also know there is no point being angry at you, Shinomiya.\n\nShiori: ...Come in. You will get wet.\n\n[label s08_open]\n\n[if trust_shiori < 2 -> s08_alone]\n\n[show shiori normal]\n\nShiori: I am opening it. I promised.\n\nMinato: (Shiori set a paper knife on the counter and took one deep breath.)\n\n[jump s08_read]\n\n[label s08_alone]\n\n[show shiori normal]\n\nShiori: I thought about it alone last night.\n\nShiori: In the end, someone has to know what is inside before my grandfather reads it. His eyes are bad.\n\nShiori: ...You can just watch. I am the one who will read it.\n\n[label s08_read]\n\n[se paper]\n\nMinato: (The sound of the seal tearing echoed louder than I expected.)\n\nMinato: (Inside were two sheets of letter paper. One was old, its edges gone brown. The other was newer.)\n\n[bg letter_cg]\n[bgm bgm_memory]\n\nShiori: \"Dear Dad,\"\n\nShiori: \"I wrote this letter in the winter of my third year of high school. I wrote it meaning to send it, and couldn't.\"\n\nShiori: \"You and Mom split up, I went with Mom, and I became a Minase. I think the reason I still decided to go to high school in this town was this shop.\"\n\nShiori: \"Taking the library job was really just because I wanted an excuse to come to the shop. I think you knew.\"\n\nShiori: \"I'm sorry for always writing at the desk by the window. Never reading, just spreading out my notebooks. I can't complain if you call me 'a girl who doesn't take care of books.'\"\n\nMinato: (Shiori's voice stopped for a moment.)\n\nShiori: \"I'm going to Tokyo. I know you'd be against it, so I'm going without telling you.\"\n\nShiori: \"But this shop is my favorite place in the world. That's the one thing I wanted to make sure I wrote down.\"\n\nShiori: \"I loved sheltering from the rain here on rainy days.\"\n\n[se paper]\n\nShiori: ...There is another sheet.\n\nShiori: \"More than ten years later, I'm finally sending this. It turned up at the back of a drawer.\"\n\nShiori: \"I have a daughter. She's six. She loves books. She takes much better care of them than I ever did.\"\n\nShiori: \"Her name is Shiori—like a bookmark. I named her in this shop.\"\n\nShiori: \"Someday I'll bring her. When I do, please lend her the desk by the window. Haruka\"\n\n[bg shop_night]\n[bgm bgm_rain]\n[se rain_loop]\n\n[show shiori sad]\n\nMinato: (Shiori didn't move for a while, the letter still in her hands.)\n\n\nShiori: ...\n\nMinato: (Shiori was gently pressing her thumb over her own name on the second sheet.)\nMinato: ...The postmark was June, ten years ago, right?\n\nShiori: My mother died that autumn.\n\nMinato: ...\n\nShiori: \"I'll bring her,\" she said.\n\nShiori: So she never got to bring me here.\n\nMinato: (I felt like I had to say something. Nothing came.)\n\nMinato: (Instead, I pushed the box of tissues at the end of the counter to where Shiori could reach it.)\n\n[show shiori normal]\n\nShiori: ...That's what you do.\n\nMinato: Hm?\n\nShiori: Nothing.\n\nShiori: The letter arrived the same week Shinomiya—your sister—borrowed the book, didn't it?\n\nMinato: My sister's card was from the same week.\n\nShiori: My grandfather has a habit of putting the mail on top of piles of books. He still does.\n\nMinato: So the letter that arrived got slipped into a book on the returns shelf—\n\nShiori: And spent ten years on the Shinomiya family's bookshelf.\n\nMinato: ...I'm going to have a proper talk with my sister.\n\n[show shiori smile]\n\nShiori: It is not your sister's fault. It is my grandfather's.\n\nShiori: Besides, because your sister kept it for ten years, you came to return it, Minato.\n\nMinato: (She called me by my name.)\n\n[show shiori normal]\n\nShiori: Tomorrow I am going to the hospital. I will read this to my grandfather.\n\nShiori: ...Will you come with me?\n\nMinato: I'll come.\n\n[bgm stop]\n[bg black]\n","scenes/en/scene09.md":"# Scene 09 The Hospital Room\n\n[bg hospital_room]\n[bgm bgm_memory]\n\nMinato: (The next afternoon. Shiomi General Hospital, fourth floor, the private room at the very end.)\n\nMinato: (Outside the window, for once, it was sunny.)\n\nMinato: (In front of the nurses' station, Shiori stopped for a moment.)\n\n[show shiori normal]\n\nShiori: ...I will tell you now. My grandfather probably will not say anything.\n\nMinato: Okay.\n\nShiori: He might get angry. Since I opened it without asking.\n\nMinato: Then I'll get yelled at too.\n\nShiori: He will say you have nothing to do with it, Shinomiya.\n\nMinato: Then I'll wait in the hall.\n\nShiori: ...Come. All the way in.\n\n[hide shiori]\n\n[se door_slide]\n\n[show soichiro normal]\n\nSoichiro: ...Who's that?\n\n[show shiori normal]\n\nShiori: The one who returned the book with the letter. Shinomiya.\n\nMinato: Hello.\n\nSoichiro: ...I see.\n\nMinato: (White hair. Round glasses. A gray vest—apparently worn on purpose over his hospital pajamas.)\n\nSoichiro: Shinomiya. ...The elder daughter, then. The one who kept a book for ten years.\n\nMinato: That's my sister. I'm sorry.\n\nSoichiro: We don't charge late fees.\n\nShiori: I told him that, too.\n\nSoichiro: ...I see.\n\nMinato: (They say it the exact same way, I thought. Shiori didn't seem to notice.)\n\n[show shiori sad]\n\nShiori: Grandpa. I opened the letter.\n\nSoichiro: ...\n\nShiori: I'm going to read it.\n\nSoichiro: I didn't ask you to.\n\nShiori: You didn't.\n\nMinato: (Mr. Kuze turned toward the window. But he didn't cover his ears.)\n\n[se paper]\n\nMinato: (Shiori read it from the beginning, in the same voice she'd used at the shop.)\n\nMinato: (From \"Dear Dad\" all the way to \"please lend her the desk by the window.\")\n\nMinato: (Just once, partway through, Mr. Kuze's shoulders moved. It was at \"a girl who doesn't take care of books.\")\n\n[show shiori normal]\n\nShiori: ...Haruka, it says.\n\nShiori: You said you didn't know the handwriting.\n\n[show soichiro normal]\n\nSoichiro: ...I did.\n\nShiori: Why?\n\nSoichiro: I didn't know it.\n\nSoichiro: Her handwriting in high school was far messier.\n\nShiori: ...\n\nSoichiro: The second sheet—that hand I don't know. A grown woman's hand. I hadn't seen it in over ten years.\n\nMinato: (Mr. Kuze slowly took off his glasses and wiped the lenses. They didn't look like they needed it.)\n\nSoichiro: She was a girl who didn't take care of books.\n\nShiori: You told me that before.\n\nSoichiro: She wrote in the books I lent her. In the margins. Next to the characters' lines, she'd add lines of her own. No matter how many times I told her, she wouldn't stop.\n\nSoichiro: ...Thanks to her, half the books in the shop are unsellable.\n\n[show shiori surprised]\n\nShiori: Half?\n\nSoichiro: The shelf by the window. Every one of those has Haruka's scribbles in it.\n\nMinato: (When we were packing, Shiori had told me \"not yet\" about the window shelf, and I'd left it alone.)\n\nShiori: ...You didn't throw them away.\n\nSoichiro: As if I would.\n\n[show soichiro gentle]\n\nSoichiro: She was a girl who laughed a lot.\n\nSoichiro: When it rained, she'd come running without an umbrella and take shelter in the shop. I'd tell her to go home; she wouldn't. I'd offer to lend her an umbrella; she wouldn't take it.\n\nSoichiro: She said if she borrowed an umbrella, she'd have no reason left to shelter from the rain.\n\nMinato: (I thought of the indigo umbrella. The one big enough for two.)\n\nSoichiro: She named the shop, too.\n\nShiori: It's Kuze Lending Library, isn't it?\n\nSoichiro: On the sign, yes. She called it \"the shelter.\" \"The Lending Library in the Rain.\" Told her friends so, too, apparently.\n\nSoichiro: Even the school library lot started calling it that.\n\n[show shiori sad]\n\nShiori: ...And my name, too.\n\nSoichiro: I didn't know.\n\nSoichiro: At the funeral, when I took you in, that's the first I heard your name. ...So. She named you in the shop.\n\nMinato: (Mr. Kuze didn't take the letter. But he never took his eyes off the pages resting on Shiori's lap.)\n\n[show soichiro normal]\n\nSoichiro: Shinomiya.\n\nMinato: Yes?\n\nSoichiro: Books are meant to be brought back.\n\nMinato: ...Yes.\n\nSoichiro: And when you bring one back, you borrow another. That's how it works.\n\nSoichiro: Close the shop, and that can't happen anymore.\n\n[show shiori surprised]\n\nShiori: Grandpa.\n\nSoichiro: Shiori. Do as you see fit. I can't stand behind that counter anymore.\n\nSoichiro: ...Don't throw out the window shelf.\n\n[se door_slide]\n\nMinato: (When we left the room, we could see the sea from the hallway window.)\n\n[show shiori normal]\n\nShiori: ...\"Do as you see fit.\" That's the first time he's ever said that to me.\n\nMinato: What does he usually say?\n\nShiori: \"Do whatever you want.\"\n\nMinato: Sounds similar.\n\nShiori: It's completely different.\n\n\nMinato: (While we waited for the elevator, Shiori put the letter back in its envelope and tucked it into her apron—no, her uniform pocket.)\n\nShiori: I couldn't give it to him.\n\nMinato: He didn't take it.\n\nShiori: ...But the whole time I was reading, he was listening.\n\nMinato: I saw. His shoulders moved.\n\n[show shiori smile]\n\nShiori: You notice all the wrong things, Shinomiya.\n\nMinato: I get that a lot.\n\nShiori: From whom?\n\nMinato: Chikage.\n\n[show shiori normal]\n\nShiori: ...I see.\n\nMinato: (The elevator doors opened. Shiori got in first, and before pressing \"Close,\" she waited for me, just a little.)\n\n[bgm stop]\n[bg black]\n","scenes/en/scene10.md":"# Scene 10 Night on the Seawall\n\n[bg seawall_night]\n[bgm bgm_rain]\n[se waves]\n\nMinato: (That night. The seawall, after the rain.)\n\nMinato: (The rainy-season clouds had broken up, and the lights of Shiomi were reflected in the puddles.)\n\n[if answer_later && trust_shiori < 2 -> s10_chikage]\n\n[show shiori normal]\n\nShiori: You're late.\n\nMinato: You're the one who called me out here.\n\nShiori: I told you the time, didn't I? Eight o'clock.\n\nMinato: It's 8:02.\n\nShiori: You're late.\n\nMinato: (The indigo umbrella was propped, closed, against the seawall.)\n\n[show shiori sad]\n\nShiori: When I got home, I went through every book on the window shelf.\n\nMinato: The scribbles?\n\nShiori: They were there. In every single book. In the margins.\n\nShiori: Next to a scene where the hero is crying: \"Don't cry.\" Next to a confession scene: \"Took you long enough.\"\n\nMinato: ...Just like you.\n\nShiori: Like what?\n\nMinato: Nothing.\n\n[show shiori normal]\n\nShiori: Some books had a date written on the last page. The day she finished. On rainy days, a little drawing of an umbrella.\n\nShiori: My mother came here every day, didn't she?\n\nMinato: Yeah.\n\nShiori: To the same spot where I sit every day now.\n\n[se waves]\n\nMinato: (For a while, there was only the sound of the waves.)\n\n[show shiori normal]\n\nShiori: Apparently my grandfather asked a nurse today to bring him one of the books from the window shelf.\n\nMinato: Was he reading it?\n\nShiori: Only the scribbles, she said. The nurse laughed: \"Your grandpa was holding the book upside down.\"\n\nMinato: ...Can he even read it like that?\n\nShiori: I don't think he can. He probably remembers it without reading.\n\n[show shiori sad]\n\nShiori: If you hadn't come in out of the rain that day, Shinomiya...\n\nMinato: I would have. I didn't have an umbrella.\n\nShiori: If you hadn't brought the book...\n\nMinato: My sister shoved it at me.\n\nShiori: ...It was all just chance, wasn't it?\n\nMinato: Chance is fine. The letter got delivered.\n\n[show shiori normal]\n\nShiori: Ten years late.\n\nMinato: You don't charge late fees, right?\n\nShiori: ...We don't.\n\n\n[show shiori normal]\n\nShiori: I've decided about the shop, too. I'll tell you tomorrow.\n\nMinato: Not now?\n\nShiori: If I tell you now, I'll cry.\n\nMinato: (Joke or serious—I still couldn't tell.)\n[if chose_shiori && trust_shiori < 2 -> ending_B]\n\n[jump s10_end]\n\n[label s10_chikage]\n\n[show chikage normal]\n\nChikage: Oh, there you are.\n\nMinato: Chikage. Why are you here?\n\nChikage: When you disappear, it's the roof, the library, or here. I told you.\n\nMinato: (Chikage was holding a convenience store bag.)\n\n[show chikage smile]\n\nChikage: Pork bun. You can have half.\n\nMinato: ...Thanks.\n\nChikage: So, how'd it turn out? The thing with the shop.\n\nMinato: I figured it all out. ...It was about Shiori's mom.\n\nChikage: I see.\n\n[if told_chikage -> s10_apology]\n\n[show chikage normal]\n\nChikage: I won't ask for details. I can pretty much tell from your face.\n\n[jump s10_end]\n\n[label s10_apology]\n\n[show chikage sad]\n\nChikage: I went to apologize to her today. For spreading the news about the closing.\n\nMinato: What did she say?\n\nChikage: \"Thanks to you, Hayase, I got to see the roster.\"\n\nChikage: ...She's a good kid. So good it's annoying.\n\n[label s10_end]\n\n[ending]\n","scenes/en/ending_a.md":"# END A Shiori's Bookmark\n\n[label ending_A]\n\n[show shiori normal]\n\nShiori: I've decided.\n\nMinato: Decided what?\n\nShiori: Before we close, I'm going to open the shop for one more day. \"The Last Lending Day.\"\n\nShiori: For the people on the shopping street, for our old customers, for everyone. ...And this time, I'll go tell them myself.\n\nMinato: I'll help.\n\nShiori: I didn't ask you to.\n\nMinato: I know.\n\n[show shiori smile]\n\nShiori: I figured you'd say that, so I've already counted the flyers for two people.\n\n[bg black]\n[bgm bgm_ending]\n\nMinato: (Ten days later. The last Saturday of the rainy season.)\n\n[bg shop_rain]\n[se door_bell]\n[se rain_loop]\n\nMinato: (It had been raining since morning. Shiori said it was perfect.)\n\nMinato: (Umbrellas lined up outside the shop. The fishmonger's wife brought dried fish, and the woman from the flower shop said \"Look how big you've gotten!\" four times.)\n\nMinato: (My sister came too. She bowed to Shiori and apologized for ten years' worth of overdue time. Shiori said \"We don't charge late fees\" three times.)\n\nMinato: (On the desk by the window were the two sheets of the letter, framed. Beside them, a row of scribbled-in books. \"Please feel free to read. No writing in the books.\")\n\n[show chikage smile]\n\nChikage: I brought a few people from the school library, too. To celebrate the partnership's comeback after twenty years.\n\nMinato: It's only for one day.\n\nChikage: A comeback's a comeback, even for one day.\n\n[show chikage normal]\n\nChikage: ...You're actually staying by her side, Minato. You didn't turn it into another turtle. Good job.\n\nMinato: (That was all Chikage said before heading off toward the piles of books.)\n\n\nMinato: (At the end of the day, Shiori got a phone call. No—to be exact, I listened in as she called the hospital.)\n\n[se phone_ring]\n\n[show soichiro gentle]\n\nSoichiro: ...How many went out?\n\nShiori: A hundred and twenty. And lots of people came to see the window shelf.\n\nSoichiro: ...I see.\n\nShiori: The fishmonger's wife cried. She said, \"That's Haruka's handwriting.\"\n\nSoichiro: She's always been quick to cry.\n\nShiori: Did you cry too, Grandpa?\n\nSoichiro: I don't cry.\n\n[show shiori smile]\n\nMinato: (On the other end of the line, someone blew their nose. Shiori pretended not to hear.)\n\n[hide soichiro]\n[bg shop_night]\n[bgm bgm_heart]\n\nMinato: (Seven o'clock. The last customer left.)\n\n[show shiori normal]\n\nShiori: Closing time.\n\nMinato: Closing time.\n\nShiori: My grandfather called. \"Don't throw out the shelf,\" again.\n\nMinato: You're not going to, right?\n\nShiori: I'm taking it home. The whole window shelf. My room's going to get cramped.\n\n[show shiori smile]\n\nShiori: And one more thing.\n\nMinato: (Shiori took a piece of cardstock from her apron pocket.)\n\nMinato: (A new checkout card, not yellowed at all. Stamped \"Kuze Lending Library.\" In the name field, in straight handwriting—neither round nor slanted—\"Minato Shinomiya.\")\n\nMinato: What's this?\n\nShiori: Your checkout card, Minato. The very last one.\n\nMinato: What are you lending me?\n\n[show shiori blush]\n\nShiori: ...Figure that out yourself.\n\nShiori: No due date.\n\nMinato: (Outside, the rain eased a little.)\n\nMinato: (In the umbrella stand, just one big indigo umbrella was left. The one bought for two.)\n\n[title END A「栞のしおり」]\n[end]\n","scenes/en/ending_b.md":"# END B After the Rain\n\n[label ending_B]\n\n[show shiori normal]\n\nShiori: We're closing at the end of the month, as planned.\n\nMinato: ...I see.\n\nShiori: My grandfather said to do as I see fit, but even if I do, I can't run it alone.\n\nShiori: Besides, I'm the one who decided to close. I want to see what I decided through to the end.\n\nMinato: Yeah.\n\n[show shiori sad]\n\nShiori: I'm only taking the window shelf home.\n\nMinato: The scribbled one.\n\nShiori: The scribbled one.\n\n[se waves]\n\nMinato: (After that, I went to the shop a few more times before the end of the month. The packing was finished around noon on the last day.)\n\nMinato: (The empty shelves looked smaller than I expected.)\n\n[bg shop_night]\n[bgm bgm_rain]\n\n[show shiori normal]\n\nShiori: Four thousand two hundred and eleven books. All in boxes.\n\nMinato: I packed half of them.\n\nShiori: A third.\n\nMinato: You were counting?\n\nShiori: I was keeping the ledger.\n\nMinato: (A used bookstore was apparently taking all the boxes. Only the window shelf would go to Shiori's room.)\n\n[show shiori sad]\n\nShiori: Yesterday my grandfather talked about my mother, just a little.\n\nMinato: What did he say?\n\nShiori: \"She never borrowed the umbrella.\" Just that. Three times.\n\nMinato: ...\n\nShiori: If he said it three times, I think he probably always wanted to lend it to her.\n\n[show shiori normal]\n\nShiori: I left that umbrella in my grandfather's room. By the window of his hospital room.\n\nMinato: Think he'll use it once he's discharged?\n\nShiori: I don't think so. He's someone who doesn't go out on rainy days.\n\nMinato: Then why'd you leave it there?\n\nShiori: ...I wonder why.\n\nMinato: (She said it the same way she did on the first day. But this time, I felt like I knew the reason.)\n\n[bg seawall_eve]\n[bgm bgm_ending]\n[se waves]\n\nMinato: (The evening of the closing day. The TV said the rainy season seemed to be over.)\n\n[show shiori normal]\n\nShiori: It cleared up.\n\nMinato: It did.\n\nShiori: There's no reason left to shelter from the rain.\n\nMinato: (She didn't have the indigo umbrella with her today.)\n\nShiori: Shinomiya.\n\nMinato: Hm?\n\nShiori: Thank you for coming to return the book.\n\nMinato: It was my sister's book, though.\n\n[show shiori smile]\n\nShiori: I know.\n\nShiori: ...If it rains again.\n\nMinato: Yeah.\n\nShiori: I might be sheltering from the rain somewhere.\n\nMinato: I'll look for you.\n\nShiori: And if you can't find me?\n\nMinato: I'll look again the next time it rains.\n\n[show shiori normal]\n\nShiori: ...You're a strange person.\n\nMinato: I get that a lot.\n\n[se waves]\n\nMinato: (Shiori didn't wave. She gave a small bow and walked off along the seawall.)\n\nMinato: (The sky was clear all the way to the horizon.)\n\n[title END B「雨上がり」]\n[end]\n","scenes/en/ending_c.md":"# END C The Seat Beside Me\n\n[label ending_C]\n\n[show chikage normal]\n\nChikage: Hey, Minato.\n\nMinato: Hm?\n\nChikage: You couldn't have solved that shop's mystery without my rosters, right?\n\nMinato: ...I guess not.\n\n[show chikage smile]\n\nChikage: Then I win.\n\nMinato: Win what?\n\nChikage: No idea. But I win.\n\n[se waves]\n\nMinato: (Chikage sat on the edge of the seawall and split what was left of the pork bun in half.)\n\n[bg black]\n[bgm bgm_ending]\n\nMinato: (Then the end of the month came. Kuze Lending Library closed.)\n\nMinato: (On the last day, I heard a lot of people from the shopping street showed up. I didn't go. I didn't know if I should.)\n\nMinato: (A few days later, a cardboard box arrived at the school library. Inside were ten old books with scribbles in the margins.)\n\nMinato: (The note tucked in with them said only: \"The partnership's last loan. No due date. —Kuze\")\n\nMinato: (I couldn't tell which Kuze it was. The handwriting was straight—neither round nor slanted.)\n\nMinato: (Just once, the day before the closing, I passed Shiori on the shopping street. She was carrying the indigo umbrella.)\n\nMinato: (Shiori nodded and said, \"Thank you for everything.\" Polite and formal, just like the first day.)\n\nMinato: (I thought that was okay. I decided to think so.)\n\nMinato: (I heard the letter was sitting by the window of Mr. Kuze's hospital room. Chikage got that from the fishmonger's wife.)\n\n[bg library]\n[bgm bgm_daily]\n[se school_chime]\n\n[show chikage normal]\n\nChikage: Every one of these has writing in it. Totally against the rules for library books.\n\nMinato: Into the stacks?\n\n[show chikage smile]\n\nChikage: No way. I'm putting them next to the counter. With a sign that says \"No writing in the books.\"\n\nMinato: (Chikage opened the top book and traced the round handwriting in the margin with her finger.)\n\nChikage: \"Took you long enough,\" it says. Next to the confession scene.\n\nMinato: ...\n\n[show chikage pout]\n\nChikage: What?\n\nMinato: Nothing.\n\nChikage: Just say it.\n\nMinato: The turtle.\n\nChikage: That again?\n\nMinato: You were the one who took it back. After I got bored.\n\nChikage: Yeah.\n\nMinato: When you were crying back then... was it because you felt sorry for the turtle?\n\n[show chikage surprised]\n\nChikage: ...You're asking that now?\n\nMinato: I feel like I can answer now.\n\n[show chikage sad]\n\nChikage: Because I thought you were going to wander off somewhere again.\n\nMinato: (Outside the window, it had started to rain.)\n\nMinato: Chikage.\n\n[show chikage normal]\n\nChikage: What?\n\nMinato: About my answer from the other day.\n\n[show chikage surprised]\n\nChikage: ...Wait, here? In the library?\n\nMinato: I forgot my umbrella. I can't go home for a while.\n\nMinato: So while I'm sheltering from the rain, I want you to hear it.\n\n[show chikage smile]\n\nChikage: ...That's so not fair.\n\nChikage: Fine. Sit next to me.\n\n[title END C「となりの席」]\n[end]\n","scenes/zh/scene01.md":"# Scene 01 避雨的租书屋\n\n[bg street_rain]\n[bgm bgm_rain]\n[se rain_heavy]\n\n湊: （……天气预报也太不准了吧。）\n\n湊: （我把书包顶在头上跑。商店街的拱廊顶棚到一半就断了。）\n\n湊: （满街都是拉下的卷帘门，只有一家还亮着灯。）\n\n[se door_slide]\n[se door_bell]\n[bg shop_rain]\n[se rain_loop]\n\n湊: 不好意思，就待一会儿——\n\n[show shiori cold]\n\n栞: 七点关门。\n\n湊: 啊，我只是避个雨。马上就走。\n\n栞: ……伞架在那边。身上湿着的话，请不要碰书架。\n\n湊: （我没带伞。不过没说出口。）\n\n湊: （有股旧纸张的味道。书一直塞到天花板，书脊全都被晒得褪了色。）\n\n湊: 这里是书店？\n\n[show shiori normal]\n\n栞: 是租书屋。\n\n湊: 租书屋。\n\n栞: 就是借书、看完、再还回来的店。\n\n湊: ……哦。\n\n湊: （说起来——我翻了翻书包。今天早上姐姐硬塞给我的一本书。）\n\n湊: 这本，应该是你们店的。我姐说她以前借了一直忘了还。\n\n[show shiori surprised]\n\n栞: ……「久世租书店」。是我们家的。\n\n栞: 不过借出日期是十年前。\n\n湊: 抱歉。那个，要交滞纳金吗……\n\n栞: 我们店不收那种东西。\n\n[se book_drop]\n\n湊: 啊。\n\n湊: （栞伸手接过时，书从她手里掉了下去。）\n\n[se paper]\n\n湊: （一个白色信封从书页间滑了出来。）\n\n湊: 里面夹着东西。\n\n[show shiori normal]\n\n栞: 「久世先生收」……\n\n湊: 邮戳也是十年前的。\n\n栞: 封口没拆过。\n\n湊: （收件人的字迹圆圆的，微微向右倾斜。）\n\n湊: 久世先生，是店里的人？\n\n栞: 是我祖父。\n\n湊: 那，这是寄给你爷爷的——\n\n[show shiori cold]\n\n栞: 祖父现在不在这里。\n\n湊: （那语气分明在说：别再问了。）\n\n湊: （只剩下雨声还在继续。）\n\n[choice]\n- 「要不要打开看看？」 -> choice01_a\n- 「还是交给你爷爷比较好吧。」 -> choice01_b\n[/choice]\n\n[label choice01_a]\n\n湊: 要不要打开看看？\n\n[show shiori cold]\n\n栞: 这是别人的信。\n\n湊: ……也是。抱歉。\n\n栞: 不过。\n\n湊: 嗯？\n\n[show shiori normal]\n\n栞: ……不，没什么。\n\n[jump scene01_end]\n\n[label choice01_b]\n[flag trust_shiori +1]\n\n湊: 还是交给你爷爷比较好吧。毕竟都等了十年了。\n\n[show shiori surprised]\n\n栞: 你是说，等了十年的是这封信？\n\n湊: 两边都是吧？\n\n[show shiori normal]\n\n栞: ……你这人真奇怪。\n\n湊: 经常有人这么说。\n\n[jump scene01_end]\n\n[label scene01_end]\n\n[se rain_loop]\n\n湊: （雨渐渐小了。）\n\n湊: 那我先走了。书能还回来真是太好了。\n\n栞: 那个。\n\n[show shiori sad]\n\n栞: 这家店，这个月底就要关门了。\n\n湊: 诶？\n\n栞: 我还没跟任何人说过。……请你也不要说出去。\n\n湊: 那为什么告诉我？\n\n栞: 为什么呢。\n\n[show shiori normal]\n\n栞: 也许是因为，你是十年来第一个回来还书的人吧。\n\n[se door_bell]\n\n湊: （走出门外，细细的雨还在下。）\n\n湊: （回头望去，玻璃门后，她正把那个信封举向灯光。）\n\n[bgm stop]\n[bg black]\n","scenes/zh/scene02.md":"# Scene 02 第二天早上：从教室到图书室\n\n[bg library]\n[bgm bgm_daily]\n[se school_chime]\n\n湊: （第二天早上。雨在夜里就停了。）\n\n湊: （从第一节课到第四节课，黑板上的字几乎一个都没进脑子。）\n\n湊: （圆圆的字。向右倾斜的收信人。十年前的邮戳。）\n\n湊: （午休时，回过神来我已经在图书室了。在这里没人会跟我搭话。）\n\n[show chikage normal]\n\n千景: 找到了。\n\n湊: ……你怎么知道的。\n\n千景: 湊午休一消失，不是在这儿就是在天台。天台今天湿透了嘛。\n\n湊: 你是侦探吗。\n\n千景: 我是图书委员。今天轮到我值柜台。\n\n湊: （千景把胳膊肘撑在柜台上，开始整理一堆还回来的书。）\n\n[show chikage smile]\n\n千景: 所以呢？\n\n湊: 什么所以。\n\n千景: 都写在脸上了。从早上开始就一直是一副在想事情的表情。\n\n湊: 没什么。在想数学小测验的事。\n\n千景: 你从小学起就没担心过一次小测验好吗。\n\n湊: ……\n\n千景: 你看。\n\n湊: （没法反驳。我和千景从幼儿园就认识了，这种时候撒谎从来没成功过。）\n\n[show chikage normal]\n\n千景: 啊，对了。湊，你是住在商店街那边吧？\n\n湊: 住在它后面。\n\n千景: 你知道「久世租书店」吗？跟鱼店在一排的那家老店。\n\n湊: （我的手停住了。）\n\n湊: ……知道是知道。\n\n千景: 我整理书库的时候翻出一本旧台账。说是以前这个图书室跟那家店有合作。\n\n湊: 合作？\n\n千景: 好像是图书室没有的书，就从那家店借来再借给学生。不过是挺久以前的事了。老师也只记得「啊，好像是有过」。\n\n湊: 哦。\n\n[show chikage surprised]\n\n千景: ……你刚才那声「哦」不太对劲。\n\n湊: 没有不对劲。\n\n千景: 就是不对劲。湊真没兴趣的时候会说「嗯——」。\n\n湊: （连这个都被摸透了吗。）\n\n[show chikage normal]\n\n千景: 怎么了？你跟那家店有什么事吗？\n\n湊: （我想起昨天那个信封。还有关门的事。）\n\n湊: （关门的事，她叫我别说。信的事——她没说。）\n\n[choice]\n- 把信的事告诉千景 -> choice02_a\n- 含糊地糊弄过去 -> choice02_b\n[/choice]\n\n[label choice02_a]\n[flag told_chikage = 1]\n\n湊: ……昨天，我进那家店避雨了。\n\n湊: 顺便去还我姐十年前借了没还的书。结果书里掉出来一封信。\n\n[show chikage surprised]\n\n千景: 信？\n\n湊: 封口都没拆。收信人是店里的老爷爷，邮戳是十年前的。\n\n千景: 欸，什么啊。这根本就是案件吧。\n\n湊: 算不上案件吧。\n\n千景: 一封十年都没送到的信耶？绝对算案件了。\n\n[show chikage smile]\n\n千景: 那，寄信人是谁？\n\n湊: 没写。只知道字圆圆的。\n\n千景: 圆圆的字。就是说像女生写的？\n\n湊: 大概吧。\n\n千景: 嗯——\n\n湊: ……干嘛。\n\n千景: 没什么呀？店里有看店的人吗？\n\n湊: 有。说是孙女。\n\n千景: 那女生可爱吗？\n\n湊: 跟这没关系吧。\n\n千景: 你没否认嘛。\n\n湊: （午休剩下的十分钟，千景一边翻台账一边一直在坏笑。）\n\n[show chikage normal]\n\n千景: 合作的记录，我再帮你查查。有什么发现就告诉你。\n\n湊: ……帮大忙了。\n\n[jump scene02_end]\n\n[label choice02_b]\n\n湊: 以前我姐好像在那儿借过书。就这样。\n\n[show chikage pout]\n\n千景: 就这样？\n\n湊: 就这样。\n\n千景: ……哦，是吗。\n\n湊: （千景扫还书条形码的力气比平时大了一点。）\n\n[show chikage normal]\n\n千景: 不想说就算了。不过湊，你可不擅长藏秘密哦。\n\n湊: 我知道。\n\n千景: 知道就别藏了。\n\n湊: （我没有回答。）\n\n[label scene02_end]\n\n[se school_chime]\n\n湊: （预备铃响了。千景抱着一摞书消失在书库里。）\n\n湊: （窗外又开始阴下来了。）\n\n湊: （放学后，再去一次那家店吧。理由——之后再想就好。）\n\n[bg black]\n[se door_slide]\n\n湊: （回家路上，我给姐姐发了消息：「十年前那本书，你为什么没还？」）\n\n湊: （三分钟后回复来了。「我以为还了」「出什么事了？」）\n\n湊: （我打了「里面夹着一个信封」，又删掉了。发了句「没什么」。）\n\n湊: （「那家的老爷爷还好吗？虽然很凶，但人很温柔哦」）\n\n湊: （我已读了，却盯着屏幕看了好一会儿。）\n\n[bgm stop]\n[bg black]\n","scenes/zh/scene03.md":"# Scene 03 租书屋，第二次\n\n[bg street_rain]\n[bgm bgm_rain]\n[se rain_loop]\n\n湊: （放学后。跟天气预报说的一样，又下起雨来了。）\n\n湊: （今天我在便利店买了伞。透明的那种。）\n\n[se door_slide]\n[se door_bell]\n[bg shop_rain]\n\n[show shiori surprised]\n\n栞: ……\n\n湊: 你好。\n\n[show shiori cold]\n\n栞: 你还有别的书没还吗？\n\n湊: 没有。\n\n栞: 那是来避雨的？你带着伞吧。\n\n湊: 带着。\n\n栞: ……\n\n湊: 我想来帮忙。要关门的话，总得收拾东西吧。\n\n[show shiori normal]\n\n栞: 我没拜托你。\n\n湊: 我知道。\n\n湊: （栞沉默了一会儿，然后指了指店里面。）\n\n栞: 里面那排，从第三层往下。全部装箱。书脊朝上，按编号顺序。\n\n湊: 明白。\n\n栞: 请不要用湿手碰。\n\n湊: 擦过了。\n\n栞: 伞也放到外面。\n\n湊: ……是。\n\n[se footsteps_wet]\n\n湊: （工作比想象中枯燥。抽出书，核对编号，放进箱子。一遍又一遍。）\n\n湊: （栞在收银台旁边默默记账。只有笔声和雨声。）\n\n湊: 这些编号是什么？\n\n栞: 进货的顺序。全是祖父亲手写的。\n\n湊: 全部？\n\n栞: 全部。四千二百一十一本。\n\n湊: 真厉害。\n\n栞: 不过他字太丑，有一半左右认不出来。\n\n湊: （我判断不出这是不是在开玩笑。）\n\n湊: 你爷爷今天不在吗？\n\n[show shiori sad]\n\n栞: 住院了。从春天开始。\n\n湊: ……这样啊。\n\n栞: 是心脏。手术已经做完了，不是有生命危险的那种。只是，以后没法再站在店里了。\n\n湊: 所以才要关门。\n\n栞: 我一个人撑不下去。\n\n湊: （笔声停了。）\n\n栞: 那封信，昨天我带去医院了。\n\n湊: 给他了？\n\n栞: 给他看了。只看了收信人。\n\n湊: 他怎么说？\n\n栞: 「不认识这个字。」\n\n湊: ……\n\n栞: 就说了这一句，然后把脸转向窗户那边了。\n\n[show shiori normal]\n\n栞: 所以，信还在我这儿。\n\n湊: （栞从围裙口袋里把信封的一角稍微露出来给我看。）\n\n湊: 那查一下是谁写的不就行了？\n\n栞: 查了又能怎样。\n\n湊: 要是其实认识这个字，说不定他就会收下了。\n\n[show shiori surprised]\n\n栞: ……\n\n湊: 既然是十年前的邮戳，也许是十年前常来店里的某个人。没留下什么记录吗？\n\n栞: 借书卡倒是有。还回来的书的卡片，全都留着。\n\n湊: 全部？\n\n栞: 祖父是那种什么都不扔的人。\n\n[se paper]\n\n湊: （栞从里面搬出三个鞋盒。里面塞满了发黄的硬纸卡片。）\n\n湊: （日期、名字、归还章。光是十年前的就有一百多张。）\n\n栞: 只看十年前梅雨季的。邮戳是六月。\n\n湊: 不知道有没有我姐的名字。\n\n栞: 篠宫……有了。是同一周。\n\n湊: （我姐的字，那时候就跟现在一样难看。）\n\n湊: （剩下的卡片，我们两个分头翻。）\n\n[choice]\n- 把借书卡的背面一张张检查 -> choice03_a\n- 再仔细看看信封上的字 -> choice03_b\n[/choice]\n\n[label choice03_a]\n[flag found_stamp = 1]\n\n湊: （光看正面的名字，找不到决定性的线索。我翻过来看看。）\n\n湊: （大多是空白。但有几张盖着淡淡的朱红色圆章。）\n\n湊: 这是什么章？\n\n[show shiori surprised]\n\n栞: ……「潮见高中图书室」。\n\n湊: 是我们学校。\n\n栞: 有过合作的。以前店里会把书借给学校的图书室。\n\n湊: 这个我今天刚听说。\n\n栞: 听谁说的。\n\n湊: 当图书委员的熟人。\n\n湊: （我把盖了章的卡片排开。其中一张很旧的，日期还要早得多的卡片上，有我见过的字。）\n\n湊: 这张。\n\n栞: 「图书室代借　负责人」……名字那里糊掉了。\n\n湊: 可是，这个字。\n\n[show shiori normal]\n\n栞: ……圆圆的。往右斜。\n\n湊: 跟信封一样。\n\n栞: 这可是二十多年前的卡片。\n\n湊: 嗯。\n\n栞: 十年前写信的人，更早以前就来过我们店……？\n\n湊: 而且还是学校图书室的负责人。\n\n湊: （栞把那张卡片和信封并排放着，看了很久。）\n\n[jump scene03_end]\n\n[label choice03_b]\n\n湊: 信封给我看一下。\n\n栞: 不许拆开哦。\n\n湊: 不拆。\n\n湊: （收信人写着「久世先生收」。勾很短，圆圆的。最后一点大得出奇。）\n\n湊: 我觉得是女人的字。感觉挺年轻的。\n\n[show shiori normal]\n\n栞: 是吗？\n\n湊: 我姐有个朋友就写这种字。会在笔记本边上画爱心的那种。\n\n栞: 这是偏见。\n\n湊: 大概吧。\n\n湊: （结果，那堆卡片里再也没找到更多线索。）\n\n[label scene03_end]\n\n[se rain_loop]\n\n湊: （回过神来，窗外已经黑了。）\n\n[show shiori normal]\n\n栞: 七点了。\n\n湊: 关门？\n\n栞: 关门。\n\n湊: 明天还能来吗？\n\n栞: ……箱子还剩不少。\n\n湊: 这是说可以的意思？\n\n[show shiori cold]\n\n栞: 只要不用湿手碰的话。\n\n[bgm stop]\n[bg black]\n","scenes/zh/scene04.md":"# Scene 04 商店街的雨\n\n[bg street_rain]\n[bgm bgm_mystery]\n[se rain_loop]\n\n湊: （第三天。装箱进行到一半了。）\n\n湊: （那天，栞把店门口的牌子翻成「准备中」，解下了围裙。）\n\n[show shiori normal]\n\n栞: 去打听消息。\n\n湊: 打听消息。\n\n栞: 从十年前就在这条商店街的人，说不定记得我们店的常客。\n\n湊: 跟刑侦剧似的。\n\n栞: 刑侦剧的话，人会更多一点。\n\n湊: （确实，卷帘门比人还多。）\n\n湊: （栞撑开一把旧的藏青色伞。很大，有一根伞骨是弯的。）\n\n[se umbrella_open]\n\n栞: 是祖父的。\n\n湊: 好大。\n\n栞: 听说是为了能撑两个人才买的。至于他打算跟谁一起撑，我就不知道了。\n\n湊: （我撑着便利店的透明伞，走在她旁边。）\n\n[se footsteps_wet]\n\n湊: （被褥店的老爷爷记得那家店，却不记得客人。）\n\n湊: （烟草店五年前就换了店主。）\n\n湊: （花店的大姐姐看着栞，说了三遍「都长这么大了呀」。）\n\n[show shiori sad]\n\n栞: ……一无所获呢。\n\n湊: 栞，你是在这里长大的？\n\n栞: 六岁开始。\n\n湊: 那之前呢？\n\n栞: 东京。不太记得了。\n\n湊: （我没有再问下去。）\n\n[show shiori normal]\n\n栞: 还有一家。\n\n湊: 哪家？\n\n栞: 鱼店。那家的老板娘，这条商店街的事她全知道。\n\n[se footsteps_wet]\n\n鱼店老板娘: 哎呀，这不是小栞嘛！好久不见啦，你爷爷怎么样？\n\n栞: 挺好的。闲得发慌。\n\n鱼店老板娘: 那就好。旁边这孩子是？男朋友？\n\n[show shiori cold]\n\n栞: 不是。\n\n湊: 不是。\n\n鱼店老板娘: 哎哟，还挺齐的嘛。\n\n湊: （栞稍微离我远了一点。）\n\n栞: 大概十年前，经常来我们店的客人，您还记得吗？是个女人。\n\n鱼店老板娘: 十年前啊……那时候客人还挺多的呢。\n\n鱼店老板娘: 啊，不过。\n\n栞: 不过？\n\n鱼店老板娘: 不是十年前，还要更早。很早很早以前。有个女孩子总在那儿写东西。是个高中生。\n\n湊: 写东西？\n\n鱼店老板娘: 窗边不是有张小桌子嘛。她就坐在那儿，不看书，在笔记本上写东西。宗一郎板着张吓人的脸默默看着，可也没把她赶出去。\n\n栞: ……那个人，叫什么名字？\n\n鱼店老板娘: 这个嘛，名字我可不知道。是个爱笑的孩子哦。宗一郎话那么多的样子，我也就那时候见过。\n\n[show shiori surprised]\n\n栞: 祖父……话很多？\n\n鱼店老板娘: 是啊。现在根本想象不到吧。\n\n鱼店老板娘: 后来她就不来了。大概是毕业了吧。宗一郎有好一阵子都没精神。\n\n鱼店老板娘: ……哎呀，不好意思，净说些老掉牙的事。来，这个拿着。给你爷爷的。\n\n湊: （一袋装在塑料袋里的竹荚鱼干被塞进了栞怀里。）\n\n[bgm bgm_rain]\n\n湊: （回去的路上，雨下大了。）\n\n[se rain_heavy]\n\n湊: （透明伞被风吹得啪嗒啪嗒乱晃。）\n\n[se thunder_far]\n\n湊: 啊。\n\n湊: （两根伞骨一起翻了过去。）\n\n[show shiori normal]\n\n栞: ……毕竟只要三百日元嘛。\n\n湊: 五百日元。\n\n栞: 一样的。\n\n湊: （栞什么也没说，把藏青色的伞朝我这边稍微倾斜了一点。）\n\n湊: （为了能撑两个人而买的伞。实际上，确实撑得下两个人。勉勉强强。）\n\n湊: （要保持肩膀不碰到的距离，比想象中难。）\n\n[choice]\n- 「伞我来拿吧」 -> choice04_a\n- 什么都不说，继续走 -> choice04_b\n[/choice]\n\n[label choice04_a]\n[flag trust_shiori +1]\n\n湊: 伞我来拿吧。\n\n[show shiori surprised]\n\n栞: 欸。\n\n湊: 你手腕一直弯着。老这样会累的吧。\n\n栞: ……就因为你个子高。\n\n湊: 矮的人拿的话，伞骨会戳到高的人的脑袋。\n\n[show shiori smile]\n\n栞: 呵呵。\n\n湊: （我觉得这是第一次看到她真正地笑。）\n\n栞: 那就拜托了。\n\n湊: （接过来的伞柄，比想象中凉。）\n\n湊: （栞把鱼干袋子抱在胸前，往里靠了半步。）\n\n栞: 篠宫同学，你肩膀湿了。\n\n湊: 撑伞人的宿命。\n\n栞: 这种话，你都是从哪儿学来的？\n\n湊: 我姐。\n\n栞: 你姐姐教了你很多东西呢。虽然书不还。\n\n[jump scene04_end]\n\n[label choice04_b]\n\n湊: （想说点什么，又咽了回去。）\n\n湊: （栞看着前方，两只手握着伞柄。）\n\n湊: （鱼干袋子时不时碰到我的胳膊。）\n\n[show shiori normal]\n\n栞: ……\n\n湊: ……\n\n湊: （是一种和尴尬有点不一样的沉默。）\n\n[label scene04_end]\n\n[bg shop_rain]\n[se door_bell]\n\n湊: （到了店里，栞收起伞，想用手指把弯掉的伞骨掰直。没掰直。）\n\n[show shiori normal]\n\n栞: 「爱笑的孩子」。\n\n湊: 嗯。\n\n栞: 我想象不出祖父嘴里会说出那种话。\n\n湊: 可老板娘说她亲眼见过。\n\n栞: ……也许，我对祖父一无所知。\n\n[bgm stop]\n[bg black]\n","scenes/zh/scene05.md":"# Scene 05 图书室的旧记录\n\n[bg library]\n[bgm bgm_mystery]\n[se school_chime]\n\n湊: （第二天放学后。图书室深处，平时上着锁的书库门前。）\n\n[show chikage normal]\n\n千景: 喏，这个。以前的图书委员名册。大概有二十年份。\n\n湊: ……你怎么知道我会来。\n\n[if told_chikage -> s05_told]\n\n千景: 当然知道。你昨天在商店街打着伞走吧？跟租书屋那个女生一起。\n\n湊: 你看见了？\n\n[show chikage pout]\n\n千景: 是正好看见的。在鱼店门口。……所以，你在查那家店的什么？从我说合作那件事开始，你就怪怪的。\n\n湊: （到这一步，已经糊弄不过去了。）\n\n湊: ……我在找以前常去那家店的人。可能当过图书室负责人的人。\n\n千景: 哦——那是连我都不能说的事？\n\n湊: 现在不能。\n\n[show chikage normal]\n\n千景: ……算了。要看名册的话得用书库钥匙吧。我帮你开。\n\n[jump s05_search]\n\n[label s05_told]\n\n千景: 我不是说了嘛，会帮你查的。\n\n[show chikage smile]\n\n千景: 还有，今天我还叫了一个人来。\n\n湊: 啊？\n\n[se door_slide]\n\n[show shiori normal]\n\n栞: ……打扰了。\n\n湊: 栞？\n\n栞: 早濑同学往店里打了电话。说「我把名册拿出来了，你过来吧」。\n\n千景: 店里的电话号码，台账上有写嘛。\n\n湊: 你擅自就……\n\n千景: 是湊你说在找写信的人吧。当事人在场的话更快嘛。\n\n[show shiori cold]\n\n栞: 我不是当事人。我只是看店的。\n\n千景: 好好好。久世同学，请多关照。我是早濑千景。和湊从幼儿园就在一起。\n\n栞: ……我是久世。\n\n湊: （千景笑眯眯的。栞穿着别校的制服，看起来有点不自在。）\n\n[label s05_search]\n\n[se paper]\n\n湊: （名册是按学年装订的薄文件夹。手写的名字、班级、值班日。）\n\n湊: （一个学年十到十五个人。二十年的话，有两百多人。）\n\n[if found_stamp -> s05_found]\n\n湊: 只知道是「字圆圆的女生负责人」的话……\n\n[show chikage normal]\n\n千景: 光女生就有一百个哦。\n\n湊: 也是。\n\n千景: 如果有负责合作的人，那方面没有记录吗？\n\n湊: 店里什么都没留下。\n\n千景: 唔……\n\n湊: （我一本接一本地翻。字圆圆的名字有好几个。可没有一个能确定。）\n\n湊: （只有一页让我在意。二十几年前的学年。负责栏「租书屋（久世）」旁边，只写了一个名字。）\n\n湊: （那个名字上洒了一块墨渍。能看清的只有最后一个字。）\n\n湊: 「遥」……吗。\n\n千景: 遥？\n\n湊: 姓看不清。\n\n千景: 叫遥的人挺多的哦。\n\n湊: 嗯。\n\n湊: （即便如此，我还是抄进了笔记。遥。租书屋负责人。二十几年前。）\n\n[jump s05_end]\n\n[label s05_found]\n\n湊: 盖了章的那张卡片，日期是二十二年前的秋天。\n\n湊: （我抽出那一年的文件夹。）\n\n[show chikage surprised]\n\n千景: 啊，这个。负责栏写着「租书屋（久世）」。\n\n湊: 不是按星期值班，而是有专门跟店里联络的人吗。\n\n千景: 而且只有一个人。\n\n湊: （我读出那个名字。圆圆的字，稍微往右斜，是本人的笔迹。）\n\n湊: 「水濑　遥」。\n\n[if told_chikage -> s05_shiori_hears]\n\n千景: 水濑，遥。……你认识的人？\n\n湊: 不认识。\n\n湊: （可是，我认识这个字。跟信封上的字一样。）\n\n湊: （这个名字，必须告诉栞。）\n\n[jump s05_end]\n\n[label s05_shiori_hears]\n\n[show shiori surprised]\n\n栞: ……\n\n湊: 栞？\n\n栞: 水濑是我母亲结婚前的姓。\n\n[show chikage surprised]\n\n千景: 欸。\n\n栞: 遥，是我母亲的名字。\n\n湊: （书库里的空气，好像一下子变冷了。）\n\n[show shiori sad]\n\n栞: 可是，母亲应该是东京人才对。我从没听说她在这个镇上待过。\n\n千景: ……对不起。我太轻率就把你叫来了。\n\n栞: 没有。\n\n栞: 要是没被叫来，我就一直不会知道了。\n\n[label s05_end]\n\n[se school_chime]\n\n[show chikage normal]\n\n千景: 放学铃响了。书库要锁门了。\n\n湊: 嗯。\n\n千景: 呐，湊。\n\n湊: 嗯？\n\n[show chikage sad]\n\n千景: 没什么。……明天有话跟你说，给我点时间。\n\n湊: （千景说完，转着钥匙先走了出去。）\n\n[bgm stop]\n[bg black]\n","scenes/zh/scene06.md":"# Scene 06 神社石阶\n\n[bg shrine_steps]\n[bgm bgm_memory]\n[se rain_loop]\n\n湊: （那天晚上。路过店门口时，灯已经灭了。）\n\n湊: （不知怎么的，我走到了坡上的神社。石阶半中间，放着一把撑开的藏青色伞。）\n\n[show shiori normal]\n\n栞: ……你怎么在这儿。\n\n湊: 你才是。\n\n栞: 待在店里的话，眼里全是箱子。\n\n湊: （伞下，栞抱着膝盖坐着。雨已经细得几乎像雾了。）\n\n湊: 可以坐吗？\n\n栞: 那里是湿的哦。\n\n湊: 已经湿了。\n\n[se rain_loop]\n\n湊: （有好一会儿，谁都没说话。下面商店街的路灯一盏一盏地晕开。）\n\n[show shiori sad]\n\n栞: 我六岁的时候，母亲去世了。\n\n湊: ……\n\n栞: 是病死的。在东京的医院。之后，祖父收养了我，我就来了这里。\n\n栞: 父亲的事，请别问。我也不太清楚。\n\n湊: 不问。\n\n栞: 祖父一次都没提过母亲。没有照片。只有佛龛里的一块牌位。\n\n栞: 小时候，我只问过一次。「妈妈是个什么样的人？」\n\n湊: 他怎么说。\n\n栞: 「是个不爱惜书的孩子。」\n\n湊: （我差点发出奇怪的声音。）\n\n[show shiori normal]\n\n栞: ……这里是该笑的地方哦。\n\n湊: 怎么笑得出来。\n\n栞: 我笑了。因为他别的什么都不说。因为关于母亲，我只知道这个。\n\n[if found_stamp -> s06_know]\n\n湊: 可以问一下你母亲的名字吗？\n\n栞: 遥。\n\n湊: （图书室的名册。墨渍旁边残留的那一个字。）\n\n湊: ……我今天在学校的名册上看到了。二十几年前，负责和店里联络的图书委员。姓看不清，但名字是「遥」。\n\n[show shiori surprised]\n\n栞: ……\n\n湊: 鱼店老板娘说的那个在窗边写东西的女孩。信封上圆圆的字。我觉得全都是同一个人。\n\n湊: 我没确认过。只是直觉。\n\n栞: 母亲是东京人。\n\n湊: 也许只有高中的时候在这边呢。\n\n栞: ……我从没听过这种事。\n\n[jump s06_choice]\n\n[label s06_know]\n\n[if told_chikage -> s06_know_told]\n\n湊: 我今天在学校的名册上找到了。二十二年前，负责那家店和图书室联络的图书委员。\n\n湊: 一个叫「水濑遥」的人。跟信封上是同样的字。\n\n[show shiori surprised]\n\n栞: ……水濑。\n\n湊: 你知道？\n\n栞: 是母亲结婚前的姓。名字也是遥。\n\n湊: （果然，我心想。只是心想，没说出口。）\n\n[jump s06_after_know]\n\n[label s06_know_told]\n\n栞: 白天的名册。……之后我一直在想。\n\n湊: 嗯。\n\n[label s06_after_know]\n\n[show shiori sad]\n\n栞: 我一直以为母亲是东京人。\n\n栞: 可她高中的时候在这个镇上。常来我们店。和祖父聊天。\n\n栞: 祖父却说「不认识这个字」。\n\n湊: ……不可能不认识吧。\n\n栞: 不可能不认识。\n\n[label s06_choice]\n\n湊: （栞从口袋里拿出信封。边角已经有点软了。这几天，她大概摸过很多次。）\n\n[choice]\n- 「一起读吧」 -> choice06_a\n- 「由你决定就好」 -> choice06_b\n[/choice]\n\n[label choice06_a]\n\n湊: 一起读吧。如果一个人拆开太难受的话。\n\n[if trust_shiori < 1 -> s06_refuse]\n[flag trust_shiori +1]\n\n[show shiori surprised]\n\n栞: ……一起。\n\n湊: 信是从我带来的书里掉出来的。我起码也有一半责任吧。\n\n栞: 这算什么道理。\n\n湊: 就当是滞纳金。\n\n[show shiori smile]\n\n栞: ……我不是说了嘛，我们店不收滞纳金。\n\n湊: （她的敬语，稍微松动了一点。）\n\n栞: 那我就收了。拆开的时候，你要在我旁边。\n\n湊: 好。\n\n栞: 不是现在。在店里。我想在亮堂的地方好好读。\n\n[jump scene06_end]\n\n[label choice06_b]\n\n湊: 由你决定就好。拆也行，不拆也行。\n\n[if trust_shiori < 1 -> s06_refuse]\n[flag trust_shiori +1]\n\n[show shiori surprised]\n\n栞: ……我来？\n\n湊: 收信人是你爷爷，可写信的是你妈妈吧。轮不到我来决定。\n\n栞: 你觉得我可以拆祖父的信吗？\n\n湊: 觉不觉得可以，我觉得不该由我、而该由你来决定。\n\n[show shiori blush]\n\n栞: 湊，你好狡猾哦。\n\n湊: （第一次被她叫了名字。总觉得一说出来她就再也不会这么叫了，所以我没吭声。）\n\n栞: ……我拆。在店里。在读给祖父听之前，我先读。\n\n栞: 我觉得，我至少有这点权利。\n\n[jump scene06_end]\n\n[label s06_refuse]\n\n[show shiori cold]\n\n栞: ……现在还拆不了。\n\n湊: 这样啊。\n\n栞: 这不是篠宫同学你说了我就会拆的东西。\n\n湊: （信封又回到了她的口袋里。）\n\n湊: （第一天，问她要不要拆开看看的人就是我。栞大概还记得。）\n\n[show shiori normal]\n\n栞: 不过，我知道这是谁的信了。\n\n栞: ……这一点，谢谢你。\n\n[label scene06_end]\n\n[se rain_loop]\n\n湊: （雾雨停了。栞收起伞，一级一级地走下石阶。）\n\n湊: （中途她回过一次头，像要说什么，又没说。）\n\n[bgm stop]\n[bg black]\n","scenes/zh/scene07.md":"# Scene 07 千景的忠告\n\n[bg street_rain]\n[bgm bgm_daily]\n[se rain_loop]\n\n湊: （第二天放学后。千景在校门口等着。）\n\n[show chikage normal]\n\n千景: 我不是说了，给我点时间嘛。\n\n湊: 是说了。\n\n千景: 边走边说就行。反正你要去商店街那边吧。\n\n湊: （被说中了，我什么也没说，跟她并排走。）\n\n[se footsteps_wet]\n\n千景: 小学的时候，湊你从河里捡了只乌龟回来，还记得吗？\n\n湊: ……不记得。\n\n千景: 你捡回来了。然后起了名字，每天喂食，还把龟壳的花纹画下来。\n\n千景: 然后一个月就腻了，是我拿去河里放掉的。\n\n湊: 这个我记得。千景你边哭边骂我。\n\n[show chikage pout]\n\n千景: 我没哭。\n\n湊: 哭了。\n\n千景: 骂倒是骂了。\n\n[bg seawall_eve]\n[bgm bgm_heart]\n[se waves]\n\n湊: （穿过商店街，来到了防波堤。雨停了，夕阳从云缝里照下来。）\n\n[show chikage normal]\n\n千景: 湊啊，总是被感兴趣的东西整个勾走。然后一旦弄明白了，就去找下一个。\n\n湊: ……\n\n千景: 我不是在怪你。只是这样的你，我从以前就一直看着。\n\n[if told_chikage -> s07_leak]\n[jump s07_confess]\n\n[label s07_leak]\n\n[show chikage sad]\n\n千景: 还有，先让我道个歉。\n\n湊: 道什么歉。\n\n千景: 昨天晚上，我跟我妈说了租书屋的事。信的事，还有那个女生妈妈的事。我觉得是个有意思的故事。\n\n千景: 结果我妈说：「那家店好像要关门了呢。」\n\n湊: ……听谁说的。\n\n千景: 不知道。可能是谁在医院听到的。可是因为我提起了这个话题，我妈今天早上在打工的地方说出去了。\n\n千景: 到中午，整条商店街的人都知道了。\n\n湊: （栞说过，她还没告诉任何人。）\n\n湊: （没告诉老板娘，也没告诉花店。她大概是打算自己去说的吧。）\n\n千景: 刚才，我看到她在鱼店门口被好多人围着。「以后会冷清了啊」。\n\n千景: 她一直只说着「是」。\n\n湊: ……\n\n千景: 对不起。是我不好。\n\n湊: 跟你说的人是我。\n\n千景: 就算是这样。\n\n[label s07_confess]\n\n[show chikage normal]\n\n千景: 那么。说正题。\n\n湊: 刚才那不是正题吗。\n\n千景: 不是哦。\n\n湊: （千景站到防波堤边上，面朝大海。）\n\n[show chikage sad]\n\n千景: 我啊，很早以前就喜欢湊了。\n\n湊: （海浪声突然变得好大。）\n\n千景: 从乌龟那时候起。大概。\n\n湊: ……\n\n千景: 我不是为了要你回答才说的。只是觉得，什么都不说就让湊跑到别处去，我不愿意。\n\n[show chikage normal]\n\n千景: 所以，我只想问一件事。\n\n千景: 湊，你是在看着那个女生吗？还是，只是在追谜题？\n\n湊: 什么意思。\n\n千景: 那家店的谜解开了，湊大概就满足了。就像乌龟那时候一样。\n\n千景: 可是我觉得，那个女生不会满足的。店没了，妈妈的事知道了，在那之后，她的日子还要一直过下去啊。\n\n千景: 如果你明白这些还待在她身边，那就好。要是不明白，那就算了吧。\n\n湊: （千景的声音既不生气，也没哭。这一点最让我难受。）\n\n[choice]\n- 向她道谢，告诉她自己的心意在栞身上 -> choice07_a\n- 「现在没法回答」 -> choice07_b\n[/choice]\n\n[label choice07_a]\n[flag chose_shiori = 1]\n\n湊: 谢谢你，千景。\n\n[show chikage surprised]\n\n千景: ……欸，这时候说谢谢？\n\n湊: 谢谢你告诉我。谢谢你一直看着我。\n\n湊: 可是，我在意的是栞。不只是谜题。\n\n湊: 就算信的事全弄清楚了，我大概还是会去店里。装箱还没装完呢。\n\n[show chikage smile]\n\n千景: 装箱。\n\n湊: 我是认真的。\n\n千景: 我知道。都写在脸上了。\n\n[show chikage sad]\n\n千景: ……知道是知道，但我想听你说出来。\n\n湊: 嗯。\n\n千景: 那就去吧。\n\n[show chikage smile]\n\n千景: 要是像对乌龟那样对她，我就把你扔进河里。扔湊哦。\n\n[jump scene07_end]\n\n[label choice07_b]\n[flag answer_later = 1]\n\n湊: ……现在，我没法回答。\n\n[show chikage pout]\n\n千景: 真狡猾啊。\n\n湊: 对不起。\n\n千景: 这也不是该道歉的地方啦。\n\n湊: 栞的事也好，千景的事也好，我都不想随便回答。\n\n[show chikage normal]\n\n千景: ……哦——\n\n千景: 第一次听湊说「不想随便回答」这种话。\n\n湊: 是吗？\n\n千景: 是啊。你总是用一句「没什么」打发掉。\n\n[show chikage smile]\n\n千景: 那我就等你吧。不过，那个女生的信可不能让她等哦。\n\n[label scene07_end]\n\n[se waves]\n\n湊: （千景挥挥手，沿着来时的路回去了。）\n\n湊: （我想在太阳落山前去店里。）\n\n[bgm stop]\n[bg black]\n","scenes/zh/scene08.md":"# Scene 08 信\n\n[bg shop_night]\n[bgm bgm_rain]\n[se door_bell]\n\n湊: （店里的灯亮着。牌子还是「准备中」。）\n\n[if told_chikage -> s08_hurt]\n\n[show shiori normal]\n\n栞: 我就知道你会来。\n\n湊: 箱子还剩着呢。\n\n栞: 也有这个原因。\n\n[jump s08_open]\n\n[label s08_hurt]\n\n[show shiori cold]\n\n栞: ……今天已经关门了。\n\n湊: 我听说了。商店街的事。\n\n栞: 是吗。\n\n湊: 千景跟她妈妈说了，所以传开了。因为是我把信的事告诉了千景。对不起。\n\n[show shiori sad]\n\n栞: 关门的事，你没说吧。\n\n湊: 没说。可起因是我。\n\n栞: ……老板娘哭着问我：「为什么不告诉我？」\n\n栞: 我想自己去说的。对最后的每一位客人，一个一个，好好地说。\n\n湊: 嗯。\n\n栞: 我在生气。\n\n湊: 嗯。\n\n[show shiori normal]\n\n栞: 不过，我也知道冲篠宫同学生气也没用。\n\n栞: ……进来吧。会淋湿的。\n\n[label s08_open]\n\n[if trust_shiori < 2 -> s08_alone]\n\n[show shiori normal]\n\n栞: 我要拆了。说好了的。\n\n湊: （栞把裁纸刀放在柜台上，深深吸了一口气。）\n\n[jump s08_read]\n\n[label s08_alone]\n\n[show shiori normal]\n\n栞: 昨天晚上，我一个人想过了。\n\n栞: 说到底，在给祖父读之前，总得有人知道里面写了什么。祖父眼睛不好。\n\n栞: ……你只要看着就好。读的人是我。\n\n[label s08_read]\n\n[se paper]\n\n湊: （拆开封口的声音，比想象中响。）\n\n湊: （里面有两张信纸。一张很旧，边缘已经发黄。另一张比它新。）\n\n[bg letter_cg]\n[bgm bgm_memory]\n\n栞: 「爸爸：」\n\n栞: 「这封信，是我高三那年冬天写的。是打算寄出去才写的，结果没能寄出去。」\n\n栞: 「爸爸和妈妈分开，我跟了妈妈，改姓了水濑。即便这样我还是决定在这个镇上读高中，大概是因为有这家店。」\n\n栞: 「接下图书室的差事，其实也是因为想要一个来店里的借口。我想爸爸是察觉到了的。」\n\n栞: 「对不起，总是在窗边的桌子上写东西。不看书，光摊着笔记本。被说成『不爱惜书的孩子』也是没办法的。」\n\n湊: （栞的声音，停顿了一下。）\n\n栞: 「我要去东京了。爸爸肯定会反对，所以我不说就走了。」\n\n栞: 「不过，这家店是我最喜欢的地方。只有这一点，我想好好写下来。」\n\n栞: 「我最喜欢下雨天在这里避雨了。」\n\n[se paper]\n\n栞: ……还有一张。\n\n栞: 「过了十几年，事到如今才把这封信寄出去。因为它从抽屉深处冒出来了。」\n\n栞: 「我有个女儿。六岁了。喜欢书。比我爱惜得多。」\n\n栞: 「她叫栞，就是书签的那个栞。是在这家店里取的名字。」\n\n栞: 「总有一天，我会带她来。到时候，请把窗边的桌子借给她。遥」\n\n[bg shop_night]\n[bgm bgm_rain]\n[se rain_loop]\n\n[show shiori sad]\n\n湊: （栞拿着信纸，好一会儿一动不动。）\n\n\n栞: ……\n\n湊: （栞用拇指轻轻按着第二张信纸上她自己名字的地方。）\n湊: ……邮戳，是十年前的六月吧。\n\n栞: 母亲是那年秋天去世的。\n\n湊: ……\n\n栞: 她说，会带我来。\n\n栞: 结果，我没能被她带来啊。\n\n湊: （我觉得必须说点什么。却什么都说不出来。）\n\n湊: （作为替代，我把柜台边上的纸巾盒推到了栞够得着的地方。）\n\n[show shiori normal]\n\n栞: ……就是这种地方。\n\n湊: 嗯？\n\n栞: 没什么。\n\n栞: 信寄到的时候，正好是篠宫——你姐姐借书的那一周吧。\n\n湊: 我姐的卡片，是同一周的。\n\n栞: 祖父有个习惯，会把邮件放在书堆上面。现在也是。\n\n湊: 那么，寄到的信夹进了还书架上的书里——\n\n栞: 在篠宫家的书架上待了十年。\n\n湊: ……我得好好说我姐一顿。\n\n[show shiori smile]\n\n栞: 不怪你姐姐。要怪祖父。\n\n栞: 而且，正因为你姐姐十年没还，湊你才会来还书。\n\n湊: （她叫了我的名字。）\n\n[show shiori normal]\n\n栞: 明天，我要去医院。把这个读给祖父听。\n\n栞: ……你能陪我一起去吗？\n\n湊: 我去。\n\n[bgm stop]\n[bg black]\n","scenes/zh/scene09.md":"# Scene 09 病房\n\n[bg hospital_room]\n[bgm bgm_memory]\n\n湊: （第二天下午。潮见综合医院四楼，最里面的单人病房。）\n\n湊: （窗外难得是晴天。）\n\n湊: （在护士站前面，栞停下了脚步。）\n\n[show shiori normal]\n\n栞: ……先跟你说好。祖父大概什么都不会说。\n\n湊: 嗯。\n\n栞: 也许会生气。因为我擅自拆了。\n\n湊: 那我也一起挨骂。\n\n栞: 他会说跟篠宫同学没关系的。\n\n湊: 那我在走廊等。\n\n栞: ……你来。一直到里面。\n\n[hide shiori]\n\n[se door_slide]\n\n[show soichiro normal]\n\n宗一郎: ……谁啊。\n\n[show shiori normal]\n\n栞: 来还夹着信的那本书的人。篠宫同学。\n\n湊: 您好。\n\n宗一郎: ……是吗。\n\n湊: （白发。圆眼镜。灰色马甲。好像是特意套在病号服外面的。）\n\n宗一郎: 篠宫。……是那家的大女儿吧。借了十年没还的那个。\n\n湊: 是我姐。对不起。\n\n宗一郎: 我们店不收滞纳金。\n\n栞: 这话我也说过了。\n\n宗一郎: ……是吗。\n\n湊: （一模一样的说法，我心想。栞好像没发觉。）\n\n[show shiori sad]\n\n栞: 爷爷。信，我拆了。\n\n宗一郎: ……\n\n栞: 我读了哦。\n\n宗一郎: 我没让你读。\n\n栞: 你是没让。\n\n湊: （宗一郎先生把脸转向窗户。可是，他没有捂住耳朵。）\n\n[se paper]\n\n湊: （栞用和在店里读时一样的声音，从头读了一遍。）\n\n湊: （从「爸爸」开始，一直到「请把窗边的桌子借给她」。）\n\n湊: （中途只有一次，宗一郎先生的肩膀动了一下。是在「不爱惜书的孩子」那里。）\n\n[show shiori normal]\n\n栞: ……写的是「遥」。\n\n栞: 你说过不认识这个字的吧。\n\n[show soichiro normal]\n\n宗一郎: ……说过。\n\n栞: 为什么。\n\n宗一郎: 是不认识的字。\n\n宗一郎: 她高中时候的字，要难看得多。\n\n栞: ……\n\n宗一郎: 第二张，是不认识的字。是大人的字。十几年没见过了。\n\n湊: （宗一郎先生慢慢摘下眼镜，擦了擦镜片。看起来并不需要擦。）\n\n宗一郎: 是个不爱惜书的孩子。\n\n栞: 这话你以前说过。\n\n宗一郎: 在借给她的书上写字。写在空白处。在台词旁边，加上自己的台词。说多少遍都不改。\n\n宗一郎: ……都怪她，店里一半的书都卖不出去了。\n\n[show shiori surprised]\n\n栞: 一半？\n\n宗一郎: 窗边的书架。那上面全是遥乱写过的。\n\n湊: （装箱的时候，只有窗边的书架，栞说了句「先不用」，我就没动。）\n\n栞: ……你没扔啊。\n\n宗一郎: 怎么会扔。\n\n[show soichiro gentle]\n\n宗一郎: 是个爱笑的孩子。\n\n宗一郎: 一下雨，伞也不打就跑过来，在店里避雨。叫她回去也不回。我说借她伞，她也不借。\n\n宗一郎: 她说，借了伞，就没有避雨的理由了。\n\n湊: （我想起了那把藏青色的、能撑两个人的伞。）\n\n宗一郎: 店名，也是她起的。\n\n栞: 不是叫久世租书店吗。\n\n宗一郎: 招牌上是。她管这儿叫「避雨处」。「避雨的租书屋」。好像跟朋友也是这么说的。\n\n宗一郎: 连图书室那帮人，也跟着这么叫了。\n\n[show shiori sad]\n\n栞: ……栞这个名字也是。\n\n宗一郎: 我不知道。\n\n宗一郎: 葬礼上，收养你的时候，我才第一次听到你的名字。……是吗。是在店里取的啊。\n\n湊: （宗一郎先生没有接过信。可是，他的目光一直没离开栞放在膝上的信纸。）\n\n[show soichiro normal]\n\n宗一郎: 篠宫。\n\n湊: 是。\n\n宗一郎: 书，是要拿来还的。\n\n湊: ……是。\n\n宗一郎: 还了，就再借走。本来就是这么一回事。\n\n宗一郎: 店关了，就做不到了。\n\n[show shiori surprised]\n\n栞: 爷爷。\n\n宗一郎: 栞。随你的意思去做吧。我已经站不起来了。\n\n宗一郎: ……窗边的书架，别扔。\n\n[se door_slide]\n\n湊: （走出病房，从走廊的窗户能看到大海。）\n\n[show shiori normal]\n\n栞: ……「随你的意思去做」，他第一次对我这么说。\n\n湊: 平时呢？\n\n栞: 「随你的便」。\n\n湊: 听起来差不多啊。\n\n栞: 完全不一样。\n\n\n湊: （等电梯的时候，栞把信纸放回信封，又把它收进了围裙——不对，是制服的口袋里。）\n\n栞: 没能交给他。\n\n湊: 他没接呢。\n\n栞: ……不过，我读的时候，他一直在听。\n\n湊: 我看到了。肩膀动了。\n\n[show shiori smile]\n\n栞: 篠宫同学，你净看些多余的东西呢。\n\n湊: 经常有人这么说。\n\n栞: 谁说的。\n\n湊: 千景。\n\n[show shiori normal]\n\n栞: ……是吗。\n\n湊: （电梯门开了。栞先进去，在按「关」之前，稍微等了我一下。）\n\n[bgm stop]\n[bg black]\n","scenes/zh/scene10.md":"# Scene 10 防波堤之夜\n\n[bg seawall_night]\n[bgm bgm_rain]\n[se waves]\n\n湊: （那天晚上。雨后的防波堤。）\n\n湊: （梅雨的云散开了，潮见町的灯火倒映在水洼里。）\n\n[if answer_later && trust_shiori < 2 -> s10_chikage]\n\n[show shiori normal]\n\n栞: 你迟到了。\n\n湊: 是你把我叫出来的吧。\n\n栞: 我说了时间的吧。八点。\n\n湊: 八点零二分。\n\n栞: 迟到了。\n\n湊: （那把藏青色的伞收着，靠在防波堤上。）\n\n[show shiori sad]\n\n栞: 窗边书架上的书，我回去之后全看了。\n\n湊: 乱写的那些？\n\n栞: 都写了。每一本。在空白处。\n\n栞: 主角哭的场面旁边写着「别哭」。告白的场面旁边写着「太慢了」。\n\n湊: ……真像啊。\n\n栞: 像什么。\n\n湊: 没什么。\n\n[show shiori normal]\n\n栞: 还有的书在最后一页写着日期。读完的日子。下雨的日子，就画一把伞。\n\n栞: 母亲每天都来这里呢。\n\n湊: 嗯。\n\n栞: 来到我现在每天坐的地方。\n\n[se waves]\n\n湊: （好一会儿，只有海浪的声音。）\n\n[show shiori normal]\n\n栞: 听说祖父今天拜托护士，把窗边书架上的一本书拿过去了。\n\n湊: 他在读？\n\n栞: 说是只读那些乱写的字。护士笑着说：「老爷爷把书拿倒了。」\n\n湊: ……那样真的读得了吗。\n\n栞: 我觉得读不了。大概不用读也记得吧。\n\n[show shiori sad]\n\n栞: 要是那天，篠宫同学没有来避雨的话。\n\n湊: 会来的。我没带伞嘛。\n\n栞: 要是没把书带来的话。\n\n湊: 是我姐硬塞给我的。\n\n栞: ……全都是碰巧呢。\n\n湊: 碰巧也挺好的啊。信送到了嘛。\n\n[show shiori normal]\n\n栞: 晚了十年。\n\n湊: 不收滞纳金的吧。\n\n栞: ……不收。\n\n\n[show shiori normal]\n\n栞: 店的事，我也决定好了。明天告诉你。\n\n湊: 不是现在？\n\n栞: 现在说的话，我会哭的。\n\n湊: （是玩笑还是认真的，我还是分辨不出来。）\n[if chose_shiori && trust_shiori < 2 -> ending_B]\n\n[jump s10_end]\n\n[label s10_chikage]\n\n[show chikage normal]\n\n千景: 啊，在这儿。\n\n湊: 千景。你怎么在这儿。\n\n千景: 湊不见的时候，不是天台、图书室，就是这里。我说过吧。\n\n湊: （千景手里拎着便利店的塑料袋。）\n\n[show chikage smile]\n\n千景: 肉包。分你一半。\n\n湊: ……谢了。\n\n千景: 所以呢，怎么样了？那家店的事。\n\n湊: 全弄清楚了。……是栞妈妈的事。\n\n千景: 这样啊。\n\n[if told_chikage -> s10_apology]\n\n[show chikage normal]\n\n千景: 细节我就不问了。看湊的脸，大概就知道了。\n\n[jump s10_end]\n\n[label s10_apology]\n\n[show chikage sad]\n\n千景: 我今天去跟她道歉了。因为我把关门的事传出去了。\n\n湊: 她怎么说。\n\n千景: 「多亏早濑同学，我才看到了名册。」\n\n千景: ……真是个好孩子啊。好到让人生气。\n\n[label s10_end]\n\n[ending]\n","scenes/zh/ending_a.md":"# END A 栞的书签\n\n[label ending_A]\n\n[show shiori normal]\n\n栞: 我决定了。\n\n湊: 决定什么。\n\n栞: 关门之前，再开一天店。「最后的借书日」。\n\n栞: 商店街的人也好，以前的客人也好，全都通知到。……这次，我要自己去说。\n\n湊: 我帮你。\n\n栞: 我没拜托你。\n\n湊: 我知道。\n\n[show shiori smile]\n\n栞: 就知道你会这么说，传单我已经按两个人的份数好了。\n\n[bg black]\n[bgm bgm_ending]\n\n湊: （十天后。梅雨季的最后一个星期六。）\n\n[bg shop_rain]\n[se door_bell]\n[se rain_loop]\n\n湊: （从早上就在下雨。栞说「正好」。）\n\n湊: （店门口排满了伞。鱼店老板娘送来了鱼干，花店的大姐姐说了四遍「都长这么大了呀」。）\n\n湊: （我姐也来了。为十年的拖欠向栞低头道歉。栞说了三遍「我们店不收滞纳金」。）\n\n湊: （窗边的桌子上，放着装进相框的两张信纸。旁边摆着满是涂写的书。「欢迎自由阅读。禁止涂写」。）\n\n[show chikage smile]\n\n千景: 我也从图书室带了几个人来哦。就当是合作时隔二十年的复活。\n\n湊: 不过只有一天啊。\n\n千景: 一天也是复活嘛。\n\n[show chikage normal]\n\n千景: ……湊，你还真好好待在她身边了嘛。没变成乌龟那样，了不起。\n\n湊: （千景只说了这么一句，就往书堆那边去了。）\n\n\n湊: （那天结束的时候，栞打来了电话。不对，准确地说，是栞打给医院的电话，我在旁边听着。）\n\n[se phone_ring]\n\n[show soichiro gentle]\n\n宗一郎: ……借出去几本。\n\n栞: 一百二十本。还有，来看窗边书架的人，好多。\n\n宗一郎: ……是吗。\n\n栞: 鱼店老板娘哭了，说「是小遥的字」。\n\n宗一郎: 她从以前就爱哭。\n\n栞: 爷爷也哭了吗？\n\n宗一郎: 没哭。\n\n[show shiori smile]\n\n湊: （电话那头传来擤鼻涕的声音。栞装作没听见。）\n\n[hide soichiro]\n[bg shop_night]\n[bgm bgm_heart]\n\n湊: （七点。最后一位客人走了。）\n\n[show shiori normal]\n\n栞: 关门了。\n\n湊: 关门了啊。\n\n栞: 祖父打电话来了。又说「书架别扔」。\n\n湊: 不扔的吧。\n\n栞: 带回家。连窗边的书架一起。房间要变窄了。\n\n[show shiori smile]\n\n栞: 还有。\n\n湊: （栞从围裙口袋里拿出一张硬纸卡。）\n\n湊: （一张没有发黄的、崭新的借书卡。盖着「久世租书店」的章。名字栏里，用既不圆也不斜的、端端正正的字写着「篠宫 湊」。）\n\n湊: 这是什么。\n\n栞: 湊的借书卡。最后一张。\n\n湊: 你要借我什么。\n\n[show shiori blush]\n\n栞: ……这个，你自己想。\n\n栞: 没有归还期限。\n\n湊: （外面的雨，稍微小了一点。）\n\n湊: （伞架里，只剩下一把藏青色的大伞。那把为了能撑两个人而买的伞。）\n\n[title END A「栞のしおり」]\n[end]\n","scenes/zh/ending_b.md":"# END B 雨停之后\n\n[label ending_B]\n\n[show shiori normal]\n\n栞: 店还是按原计划，月底关门。\n\n湊: ……这样啊。\n\n栞: 祖父虽然说了「随你的意思」，可就算随我的意思，我一个人也撑不下去。\n\n栞: 而且，决定关门的是我。我想把自己决定的事，好好做到最后。\n\n湊: 嗯。\n\n[show shiori sad]\n\n栞: 只把窗边的书架带回家。\n\n湊: 涂写的那些。\n\n栞: 涂写的那些。\n\n[se waves]\n\n湊: （那之后到月底，我又去了几次店里。装箱在最后一天的中午完成了。）\n\n湊: （空荡荡的书架，比想象中小。）\n\n[bg shop_night]\n[bgm bgm_rain]\n\n[show shiori normal]\n\n栞: 四千二百一十一本。全都装进箱子了。\n\n湊: 有一半是我装的。\n\n栞: 三分之一。\n\n湊: 你还数了啊。\n\n栞: 因为我在记账。\n\n湊: （箱子好像会由旧书店统一收走。只有窗边书架的那部分，会去栞的房间。）\n\n[show shiori sad]\n\n栞: 祖父昨天，稍微说了一点母亲的事。\n\n湊: 说了什么。\n\n栞: 「她没借伞」。就这一句，说了三遍。\n\n湊: ……\n\n栞: 说了三遍，我想，大概他一直都很想借给她吧。\n\n[show shiori normal]\n\n栞: 那把伞，我留在祖父的房间了。病房的窗边。\n\n湊: 出院以后他会打吗。\n\n栞: 我觉得不会。他是下雨天不出门的人。\n\n湊: 那为什么留在那儿。\n\n栞: ……为什么呢。\n\n湊: （和第一天一样的说法。可这一次，我觉得我知道理由。）\n\n[bg seawall_eve]\n[bgm bgm_ending]\n[se waves]\n\n湊: （关门那天的傍晚。电视里说，梅雨好像结束了。）\n\n[show shiori normal]\n\n栞: 放晴了呢。\n\n湊: 放晴了。\n\n栞: 没有避雨的理由了。\n\n湊: （今天她没带那把藏青色的伞。）\n\n栞: 篠宫同学。\n\n湊: 嗯。\n\n栞: 谢谢你来还书。\n\n湊: 虽然是我姐的书。\n\n[show shiori smile]\n\n栞: 我知道。\n\n栞: ……要是又下雨了。\n\n湊: 嗯。\n\n栞: 我也许会在哪里避雨。\n\n湊: 我会去找。\n\n栞: 找不到呢？\n\n湊: 下一个雨天，再去找。\n\n[show shiori normal]\n\n栞: ……真是个怪人。\n\n湊: 经常有人这么说。\n\n[se waves]\n\n湊: （栞没有挥手。她轻轻低头行了个礼，沿着防波堤走远了。）\n\n湊: （天空一直晴到很远很远的地方。）\n\n[title END B「雨上がり」]\n[end]\n","scenes/zh/ending_c.md":"# END C 身旁的座位\n\n[label ending_C]\n\n[show chikage normal]\n\n千景: 呐，湊。\n\n湊: 嗯。\n\n千景: 那家店的谜，要是没有我的名册，你根本解不开吧。\n\n湊: ……是啊。\n\n[show chikage smile]\n\n千景: 那就是我赢了。\n\n湊: 比什么啊。\n\n千景: 不知道。反正我赢了。\n\n[se waves]\n\n湊: （千景坐在防波堤边上，把剩下的肉包掰成了两半。）\n\n[bg black]\n[bgm bgm_ending]\n\n湊: （之后到了月底。久世租书店关门了。）\n\n湊: （听说关门那天，商店街来了很多人。我没去。不知道自己该不该去。）\n\n湊: （过了几天，学校图书室收到了一个纸箱。里面是十本空白处有涂写的旧书。）\n\n湊: （附带的信纸上只写着：「合作的最后一次借出。没有归还期限。久世」。）\n\n湊: （我不知道这个「久世」是哪一个久世。字端端正正的，既不圆，也不斜。）\n\n湊: （关门前一天，我在商店街和栞擦肩而过一次。她打着那把藏青色的伞。）\n\n湊: （栞点头致意，说了句「承蒙关照了」。和第一天一样，用的是敬语。）\n\n湊: （我觉得这样就好。决定这么想。）\n\n湊: （听说那封信放在宗一郎先生病房的窗边。是千景从鱼店老板娘那儿打听来的。）\n\n[bg library]\n[bgm bgm_daily]\n[se school_chime]\n\n[show chikage normal]\n\n千景: 这些全都有涂写哦。作为图书室的书可是出局了。\n\n湊: 放进书库？\n\n[show chikage smile]\n\n千景: 怎么可能。放在柜台旁边。贴上「禁止涂写」。\n\n湊: （千景翻开最上面的一本，用手指描着空白处圆圆的字。）\n\n千景: 写着「太慢了」。在告白的场面旁边。\n\n湊: ……\n\n[show chikage pout]\n\n千景: 干嘛。\n\n湊: 没什么。\n\n千景: 说嘛。\n\n湊: 乌龟的事。\n\n千景: 又来？\n\n湊: 去放生的人，是千景吧。在我腻了之后。\n\n千景: 是啊。\n\n湊: 那时候你哭，是因为觉得乌龟可怜？\n\n[show chikage surprised]\n\n千景: ……现在问这个？\n\n湊: 因为觉得现在能回答了。\n\n[show chikage sad]\n\n千景: 因为我以为，湊又要跑到别的地方去了。\n\n湊: （窗外，开始下雨了。）\n\n湊: 千景。\n\n[show chikage normal]\n\n千景: 什么。\n\n湊: 上次的回答。\n\n[show chikage surprised]\n\n千景: ……欸，在这里？在图书室？\n\n湊: 我忘带伞了。暂时回不去。\n\n湊: 就当是避雨的时候顺便，听我说吧。\n\n[show chikage smile]\n\n千景: ……真狡猾啊。\n\n千景: 好吧。坐到我旁边来。\n\n[title END C「となりの席」]\n[end]\n"};
